	(1229, 1, 40, 20122, 1, '課題', 4, '手元完了(self-completed)', 1, '通常', 311, '亀井 由宇(BP)', 72, '北村 順', '[BTCM9010 インデックス再生成バッチ] インデックス再生成バッチの開発', '・チケット起票（2025/07/08）時点のメモ\r\n運用を続けることでインデックスが壊れていくため、インデックス再生成のバッチが標準にある（はず）\r\n今回の案件でも適用をするため、調査し必要に応じて修正・マスタセットアップなど行う。\r\n', '2025-07-15', '2025-07-31', 80, NULL, 0, 0, '2025-07-08 06:24:13', '2025-08-19 01:33:37', '{"id": 20122, "author": {"id": 311, "name": "亀井 由宇(BP)"}, "status": {"id": 4, "name": "手元完了(self-completed)", "is_closed": false}, "project": {"id": 25, "name": "西松屋"}, "subject": "[BTCM9010 インデックス再生成バッチ] インデックス再生成バッチの開発", "tracker": {"id": 1, "name": "課題"}, "due_date": "2025-07-31", "priority": {"id": 1, "name": "通常"}, "closed_on": null, "created_on": "2025-07-08T06:24:13Z", "done_ratio": 80, "is_private": false, "start_date": "2025-07-15", "updated_on": "2025-08-19T01:33:37Z", "assigned_to": {"id": 72, "name": "北村 順"}, "description": "・チケット起票（2025/07/08）時点のメモ\\r\\n運用を続けることでインデックスが壊れていくため、インデックス再生成のバッチが標準にある（はず）\\r\\n今回の案件でも適用をするため、調査し必要に応じて修正・マスタセットアップなど行う。\\r\\n", "spent_hours": 0.0, "custom_fields": [{"id": 18, "name": "顧客リリース日", "value": ""}, {"id": 50, "name": "水平展開", "value": null}], "estimated_hours": null, "total_spent_hours": 0.0, "total_estimated_hours": null}', '2026-05-05 08:46:33', '2026-05-05 08:41:18', '2026-05-05 08:46:39'),
	(1230, 1, 40, 20121, 2, 'バグ', 4, '手元完了(self-completed)', 1, '通常', 311, '亀井 由宇(BP)', 72, '北村 順', '[PC各機能] マテハン区分による在庫移動、発生等のチェック追加', '・チケット起票（2025/07/08）時点のメモ\r\n作業指示リスト、マテハン機器へのIFについて、出荷指示の取込時点の部門品種仕分マスタ.マテハンを参照して決めている。\r\n実際の在庫状態と合わない可能性があるため、お客様と相談し移動や在庫発生にマテハン区分・ロケの組み合わせチェックをかける方針となった。\r\nただしマスタ変更については、どのようにしたいかはお客様で検討中。\r\n', NULL, '2025-07-21', 80, NULL, 0, 0, '2025-07-08 06:22:26', '2025-07-25 08:50:20', '{"id": 20121, "author": {"id": 311, "name": "亀井 由宇(BP)"}, "status": {"id": 4, "name": "手元完了(self-completed)", "is_closed": false}, "project": {"id": 25, "name": "西松屋"}, "subject": "[PC各機能] マテハン区分による在庫移動、発生等のチェック追加", "tracker": {"id": 2, "name": "バグ"}, "due_date": "2025-07-21", "priority": {"id": 1, "name": "通常"}, "closed_on": null, "created_on": "2025-07-08T06:22:26Z", "done_ratio": 80, "is_private": false, "start_date": null, "updated_on": "2025-07-25T08:50:20Z", "assigned_to": {"id": 72, "name": "北村 順"}, "description": "・チケット起票（2025/07/08）時点のメモ\\r\\n作業指示リスト、マテハン機器へのIFについて、出荷指示の取込時点の部門品種仕分マスタ.マテハンを参照して決めている。\\r\\n実際の在庫状態と合わない可能性があるため、お客様と相談し移動や在庫発生にマテハン区分・ロケの組み合わせチェックをかける方針となった。\\r\\nただしマスタ変更については、どのようにしたいかはお客様で検討中。\\r\\n", "spent_hours": 0.0, "custom_fields": [{"id": 9, "name": "バグ混入フェーズ", "value": ""}, {"id": 2, "name": "設計担当者", "value": ""}, {"id": 11, "name": "設計書修正要否", "value": ""}, {"id": 1, "name": "設計書修正対象", "value": ""}, {"id": 4, "name": "設計書修正内容", "value": ""}, {"id": 10, "name": "設計障害原因", "value": ""}, {"id": 15, "name": "設計書修正日", "value": ""}, {"id": 3, "name": "設計書レビュー担当者", "value": ""}, {"id": 22, "name": "設計書レビュー日", "value": ""}, {"id": 8, "name": "PG修正要否", "value": "2"}, {"id": 13, "name": "PG修正担当者", "value": ""}, {"id": 16, "name": "PG修正日", "value": ""}, {"id": 14, "name": "PG障害原因", "value": ""}, {"id": 12, "name": "PG修正対象", "value": ""}, {"id": 21, "name": "PGレビュー担当者", "value": ""}, {"id": 23, "name": "PGレビュー日", "value": ""}, {"id": 20, "name": "テスト環境リリース予定日", "value": ""}, {"id": 17, "name": "テスト環境リリース日", "value": ""}, {"id": 18, "name":