	(1563, 1, 40, 19355, 1, '課題', 4, '手元完了(self-completed)', 1, '通常', 311, '亀井 由宇(BP)', 311, '亀井 由宇(BP)', '[FHCM0020_メニュー] 西松屋向けの表示改修の依頼', 'HTメニュー画面を添付のように改修をいただきたいです。\r\n※西松屋のHTでは4種類の機能分類だけ使うため\r\n\r\n■想定している修正内容\r\nmdlHtd.vb\r\n①MENU5、MENUNO5、MENU6、MENUNO6の表示を削除\r\n②MENU4、MENUNO4の表示位置を変更\r\n\r\nTMT050の登録内容\r\n①RCDKBN=\'150\'のSTRRSRV1(メニュー表示フラグ)、STRRSRV2(メニュー番号)を修正\r\n※以下サンプル\r\nINSERT INTO TMT050_NAME (CSTMCD,RCDKBN,DATACD,DATANM,DATARNM,STRRSRV1,STRRSRV2,STRRSRV3,STRRSRV4,STRRSRV5,STRRSRV6,STRRSRV7,STRRSRV8,STRRSRV9,STRRSRV10,FOREIGNNM1,FOREIGNNM2,FOREIGNNM3,FOREIGNNM4,FOREIGNNM5,FOREIGNRNM1,FOREIGNRNM2,FOREIGNRNM3,FOREIGNRNM4,FOREIGNRNM5,ENTUSRCD,ENTDATETIME,ENTPRG,UPDUSRCD,UPDDATETIME,UPDPRG) VALUES ( \'NMY\',\'0150\',\'01\',\'入荷・入庫\',\'入庫\',\'1\',\'1\',\'\',\'\',\'\',\'\',\'\',\'\',\'\',\'\',\'\',\'\',\'\',\'\',\'\',\'\',\'\',\'\',\'\',\'\',\'9999\',\'2025-01-28 00:00:00.000000\',\'SQL\',\'9999\',\'2025-01-28 00:00:00.000000\',\'SQL\');\r\nINSERT INTO TMT050_NAME (CSTMCD,RCDKBN,DATACD,DATANM,DATARNM,STRRSRV1,STRRSRV2,STRRSRV3,STRRSRV4,STRRSRV5,STRRSRV6,STRRSRV7,STRRSRV8,STRRSRV9,STRRSRV10,FOREIGNNM1,FOREIGNNM2,FOREIGNNM3,FOREIGNNM4,FOREIGNNM5,FOREIGNRNM1,FOREIGNRNM2,FOREIGNRNM3,FOREIGNRNM4,FOREIGNRNM5,ENTUSRCD,ENTDATETIME,ENTPRG,UPDUSRCD,UPDDATETIME,UPDPRG) VALUES ( \'NMY\',\'0150\',\'02\',\'出庫・出荷\',\'出庫\',\'1\',\'2\',\'\',\'\',\'\',\'\',\'\',\'\',\'\',\'\',\'\',\'\',\'\',\'\',\'\',\'\',\'\',\'\',\'\',\'\',\'9999\',\'2025-01-28 00:00:00.000000\',\'SQL\',\'9999\',\'2025-01-28 00:00:00.000000\',\'SQL\');\r\nINSERT INTO TMT050_NAME (CSTMCD,RCDKBN,DATACD,DATANM,DATARNM,STRRSRV1,STRRSRV2,STRRSRV3,STRRSRV4,STRRSRV5,STRRSRV6,STRRSRV7,STRRSRV8,STRRSRV9,STRRSRV10,FOREIGNNM1,FOREIGNNM2,FOREIGNNM3,FOREIGNNM4,FOREIGNNM5,FOREIGNRNM1,FOREIGNRNM2,FOREIGNRNM3,FOREIGNRNM4,FOREIGNRNM5,ENTUSRCD,ENTDATETIME,ENTPRG,UPDUSRCD,UPDDATETIME,UPDPRG) VALUES ( \'NMY\',\'0150\',\'03\',\'加工\',\'加工\',\'0\',\'\',\'\',\'\',\'\',\'\',\'\',\'\',\'\',\'\',\'\',\'\',\'\',\'\',\'\',\'\',\'\',\'\',\'\'