	(1594, 1, 40, 19169, 1, '課題', 2, '進行中(in progress)', 1, '通常', 332, 'LE CANH VAN(BVN)', 332, 'LE CANH VAN(BVN)', '[SPIN9020NM_入荷SCMラベル照会] QA', 'Ở tài liệu SPIN9020NM_入荷SCMラベル照会_20250313.xlsx chúng tôi cần xác nhận một số vấn đề sau:\r\n\r\n1. Ở sheet 画面レイアウト\r\n	1.1. Dòng 43, 46, 47 vì không hiển thị trên màn hình nên có thể xóa đi được không?\r\n	1.2. Dòng 53, dialog hiển thị nội dung 「取消しました。」 (MI000020) có được không?\r\n\r\n2. Ở sheetエラーチェック có cần bổ sung thêm message này không?\r\nイベント更: 新ボタン押下\r\nエラー内容: 同時にアクセスチェック\r\nメッセージ: ME000003\r\n\r\n3. Chúng tôi thực hiện câu lệnh sql để tìm kiếm dữ liệu như sau có được không?\r\n```\r\nSELECT\r\n        TIN801.ARVLRSLTDATE,\r\n        VMT050_GRPCD.DATANM,\r\n        TIN801.SCMLABEL,\r\n        VMT050_INSPCTCOMPFLG.DATANM,\r\n        TIN801.FROMCD,\r\n        TMT140.SPPLYNM,\r\n        TIN801.TOCD,\r\n        TMT160.DELINM,\r\n        TMT803.PATTERN,\r\n        TIN801.UPDDATETIME,\r\n        CASE\r\n            WHEN TIN801.GRPCD = 1 THEN 2\r\n            WHEN TIN801.GRPCD = 2 THEN 1\r\n            WHEN TIN801.GRPCD = 3 THEN 3\r\n            WHEN TIN801.GRPCD = 4 THEN 4\r\n            ELSE 0\r\n        END AS GRPCDORD\r\nFROM            \r\n        TIN801_SCMLABELRSLT AS TIN801\r\n        LEFT JOIN TMT140_SPPLY AS TMT140\r\n            ON TIN801.CSTMCD = TMT140.CSTMCD\r\n            AND TIN801.FROMCD = TMT140.SPPLYCD\r\n        LEFT JOIN TMT160_DELI AS TMT160\r\n            ON TIN801.CSTMCD = TMT160.CSTMCD\r\n            AND TIN801.TOCD = TMT160.DELICD\r\n        LEFT JOIN TMT803_ROUT AS TMT803\r\n            ON TIN801.CSTMCD = TMT803.CSTMCD\r\n            AND TIN801.TOCD = TMT803.SPPLYCD\r\n        LEFT JOIN VMT050_ALL AS VMT050_GRPCD\r\n            ON TIN801.CSTMCD = VMT050_GRPCD.CSTMCD\r\n            AND VMT050_GRPCD.LANG = \'JPN\'\r\n            AND VMT050_GRPCD.RCDKBN = \'9700\'\r\n            AND TIN801.GRPCD = VMT050_GRPCD.DATACD\r\n        LEFT JOIN VMT050_ALL AS VMT050_INSPCTCOMPFLG\r\n            ON TIN801.CSTMCD = VMT050_INSPCTCOMPFLG.CSTMCD\r\n            AND VMT050_INSPCTCOMPFLG.LANG = \'JPN\'\r\n            AND VMT050_INSPCTCOMPFLG.RCDKBN = \'9702\'\r\n            AND TIN801.INSPCTCOMPFLG = VMT050_INSPCTCOMPFLG.DATACD\r\nWHERE\r\n        TIN801.CSTMCD = \'NMY\'\r\n        AND TIN801.BRNCHCD = \'NMY001\'\r\n        AND TIN801.ARVLRSLTDATE >= \'2024/01/01\'\r\n        AND TIN801.ARVLRSLTDATE <= \'2024/01/31\'\r\n        AND TIN801.FROMCD = \'4007\'\r\n        AND TIN801.TOCD = \'4007\'\r\n        AND TIN801.SCMLABEL = \'00001940074007111202\'\r\n        AND TIN801.INSPCTCOMPFLG = \'0\'\r\n        AND TMT803.PATTERN = \'A\'\r\n        AND TIN801.GRPCD IN (\'1\', \'2\', \'3\', \'4\')\r\nORDER BY\r\n        TIN801.ARVLRSLTDATE DESC,\r\n        GRPCDORD,\r\n        TIN801.INSPCTCOMPFLG,\r\n        TIN801.SCMLABEL\r\n```', '2025-03-18', NULL, 30, NULL, 0, 0, '2025-03-17 07:43:58', '2025-03-18 08:56:25', '{"id": 19169, "author": {"id": 332, "name": "LE CANH VAN(BVN)"}, "status": {"id": 2, "name": "進行中(in progress)", "is_closed": false}, "project": {"id": 25, "name": "西松屋"}, "subject": "[SPIN9020NM_入荷SCMラベル照会] QA", "tracker": {"id": 1, "name": "課題"}, "due_date": null, "priority": {"id": 1, "name": "通常"}, "closed_on": null, "created_on": "2025-03-17T07:43:58Z", "done_ratio": 30, "is_private": false, "start_date": "2025-03-18", "updated_on": "2025-03-18T08:56:25Z", "assigned_to": {"id": 332, "name": "LE CANH VAN(BVN)"}, "description": "Ở tài liệu SPIN9020NM_入荷SCMラベル照会_20250313.xlsx chúng tôi cần xác nhận một số vấn đề sau:\\r\\n\\r\\n1. Ở sheet 画面レイアウト\\r\\n\\t1.1. Dòng 43, 46, 47 vì không hiển thị trên màn hình nên có thể xóa đi được không?\\r\\n\\t1.2. Dòng 53, dialog hiển thị nội dung 「取消しました。」 (MI000020) có được không?\\r\\n\\r\\n2. Ở sheetエラーチェック có cần bổ sung thêm message này không?\\r\\nイベント更: 新ボタン押下\\r\\nエラー内容: 同時にアクセスチェック\\r\\nメッセージ: ME000003\\r\\n\\r\\n3. Chúng tôi thực hiện câu lệnh sql để tìm kiếm dữ liệu như sau có được không?\\r\\n```\\r\\nSELECT\\r\\n        TIN801.ARVLRSLTDATE,\\r\\n        VMT050_GRPCD.DATANM,\\r\\n        TIN801.SCMLABEL,\\r\\n        VMT050_INSPCTCOMPFLG.DATANM,\\r\\n        TIN801.FROMCD,\\r\\n        TMT140.SPPLYNM,\\r\\n        TIN801.TOCD,\\r\\n        TMT160.DELINM,\\r\\n        TMT803.PATTERN,\\r\\n        TIN801.UPDDATETIME,\\r\\n        CASE\\r\\n            WHEN TIN801.GRPCD = 1 THEN 2\\r\\n            WHEN TIN801.GRPCD = 2 THEN 1\\r\\n            WHEN TIN801.GRPCD = 3 THEN 3\\r\\n            WHEN TIN801.GRPCD = 4 THEN 4\\r\\n            ELSE 0\\r\\n        END AS GRPCDORD\\r\\nFROM            \\r\\n        TIN801_SCMLABELRSLT AS TIN801\\r\\n        LEFT JOIN TMT140_SPPLY AS TMT140\\r\\n            ON TIN801.CSTMCD = TMT140.CSTMCD\\r\\n            AND TIN801.FROMCD = TMT140.SPPLYCD\\r\\n        LEFT JOIN TMT160_DELI AS TMT160\\r\\n            ON TIN801.CSTMCD = TMT160.CSTMCD\\r\\n            AND TIN801.TOCD = TMT160.DELICD\\r\\n        LEFT JOIN TMT803_ROUT AS TMT803\\r\\n            ON TIN801.CSTMCD = TMT803.CSTMCD\\r\\n            AND TIN801.TOCD = TMT803.SPPLYCD\\r\\n        LEFT JOIN VMT050_ALL AS VMT050_GRPCD\\r\\n            ON TIN801.CSTMCD = VMT050_GRPCD.CSTMCD\\r\\n            AND VMT050_GRPCD.LANG = \'JPN\'\\r\\n            AND VMT050_GRPCD.RCDKBN = \'9700\'\\r\\n            AND TIN801.GRPCD = VMT050_GRPCD.DATACD\\r\\n        LEFT JOIN VMT050_ALL AS VMT050_INSPCTCOMPFLG\\r\\n            ON TIN801.CSTMCD = VMT050_INSPCTCOMPFLG.CSTMCD\\r\\n            AND VMT050_INSPCTCOMPFLG.LANG = \'JPN\'\\r\\n            AND VMT050_INSPCTCOMPFLG.RCDKBN = \'9702\'\\r\\n            AND TIN801.INSPCTCOMPFLG = VMT050_INSPCTCOMPFLG.DATACD\\r\\nWHERE\\r\\n        TIN801.CSTMCD = \'NMY\'\\r\\n        AND TIN801.BRNCHCD = \'NMY001\'\\r\\n        AND TIN801.ARVLRSLTDATE >= \'2024/01/01\'\\r\\n        AND TIN801.ARVLRSLTDATE <= \'2024/01/31\'\\r\\n        AND TIN801.FROMCD = \'4007\'\\r\\n        AND TIN801.TOCD = \'4007\'\\r\\n        AND TIN801.SCMLABEL = \'00001940074007111202\'\\r\\n        AND TIN801.INSPCTCOMPFLG = \'0\'\\r\\n        AND TMT803.PATTERN = \'A\'\\r\\n        AND TIN801.GRPCD IN (\'1\', \'2\', \'3\', \'4\')\\r\\nORDER BY\\r\\n        TIN801.ARVLRSLTDATE DESC,\\r\\n        GRPCDORD,\\r\\n        TIN801.INSPCTCOMPFLG,\\r\\n        TIN801.SCMLABEL\\r\\n```", "spent_hours": 0.0, "custom_fields": [{"id": 18, "name": "顧客リリース日", "value": ""}, {"id": 50, "name": "水平展開", "value": null}], "estimated_hours": null, "total_spent_hours": 0.0, "total_estimated_hours": null}', '2026-05-05 08:46:33', '2026-05-05 08:41:23', '2026-05-05 08:46:44'),
