INSERT INTO `issues` (`id`, `connection_id`, `project_id`, `redmine_issue_id`, `tracker_id`, `tracker_name`, `status_id`, `status_name`, `priority_id`, `priority_name`, `author_id`, `author_name`, `assignee_id`, `assignee_name`, `subject`, `description`, `start_date`, `due_date`, `done_ratio`, `estimated_hours`, `spent_hours`, `is_closed`, `redmine_created_on`, `redmine_updated_on`, `raw_data_json`, `last_synced_at`, `created_at`, `updated_at`) VALUES
	(2577, 1, 41, 15266, 2, 'バグ', 3, '終了(completed)', 1, '通常', 202, '斎藤 雄太朗(BP)', 9, '江田 隆志', '【新WMS】【外結－バグ】【SPOT00101_受領書回収チェック表出力】【0000509】子倉庫権限しか持たないユーザで受領書回収チェック表の出力ができてしまう', '------\r\n\r\n### １．事象\r\n\r\n残_02_002#8\r\nユーザコード：TR000009\r\n\r\n④．親倉庫フィールドに、付与した子倉庫を持つ親倉庫を入力して、チェック表出力ボタンを押下する。\r\n→倉庫権限が不足している旨のエラーメッセージが表示され、印刷ができないこと。\r\n⑤．親倉庫フィールドに、付与した子倉庫を持つ親倉庫を入力して、チェック表出力ボタンを押下する。\r\n→倉庫権限が不足している旨のエラーメッセージが表示され、CSV出力ができないこと。\r\n\r\nとなっているが、どちらもエラーメッセージが表示されず④印刷および⑤CSV出力が出来てしまった\r\n\r\n以下の仕様書について、ご確認のほどよろしくお願いします。\r\n\r\nBox\\【TR】UC向けWMS構築プロジェクト\\483_総合テスト\\200_総合テスト仕様書\\410_結合残テスト\r\n総合テスト仕様書_結合残テスト_02_002.xlsx\r\n\r\n\r\n------\r\n\r\n### ２．期待結果\r\n\r\n　ログインユーザが出力対象の出荷指示ヘッダ.拠点倉庫コードの権限を持っているかチェックし\r\n　権限が無かったらエラーにする。\r\n\r\n　メッセージは「ME000409」を使用する。\r\n　メッセージは画面左上に表示する。\r\n\r\n------\r\n\r\n### ３．再現方法\r\n\r\n\r\n\r\n------\r\n\r\n### ４．原因\r\n\r\n　権限ない場合をチェックする処理が漏れたため\r\n\r\n------\r\n\r\n### ５．暫定対応\r\n\r\nなし\r\n\r\n------\r\n\r\n### ６．恒久対応\r\n\r\n権限がある場合とない場合をチェックする処理を追加し、GROUP BYを合わせて追加\r\n\r\n------\r\n\r\n### ７．特記事項\r\n\r\n　その他特記事項があれば記載（要更新）\r\n\r\n------', '2023-10-17', '2023-10-19', 100, NULL, 0, 0, '2023-10-02 08:52:19', '2023-10-20 00:19:53', '{"id": 15266, "author": {"id": 202, "name": "斎藤 雄太朗(BP)"}, "status": {"id": 3, "name": "終了(completed)", "is_closed": true}, "project": {"id": 8, "name": "トランコムWMS"}, "subject": "【新WMS】【外結－バグ】【SPOT00101_受領書回収チェック表出力】【0000509】子倉庫権限しか持たないユーザで受領書回収チェック表の出力ができてしまう", "tracker": {"id": 2, "name": "バグ"}, "category": {"id": 20, "name": "SPOT00101_受領書回収チェック表出力"}, "due_date": "2023-10-19", "priority": {"id": 1, "name": "通常"}, "closed_on": "2023-10-19T11:42:16Z", "created_on": "2023-10-02T08:52:19Z", "done_ratio": 100, "is_private": false, "start_date": "2023-10-17", "updated_on": "2023-10-20T00:19:53Z", "assigned_to": {"id": 9, "name": "江田 隆志"}, "description": "------\\r\\n\\r\\n### １．事象\\r\\n\\r\\n残_02_002#8\\r\\nユーザコード：TR000009\\r\\n\\r\\n④．親倉庫フィールドに、付与した子倉庫を持つ親倉庫を入力して、チェック表出力ボタンを押下する。\\r\\n→倉庫権限が不足している旨のエラーメッセージが表示され、印刷ができないこと。\\r\\n⑤．親倉庫フィールドに、付与した子倉庫を持つ親倉庫を入力して、チェック表出力ボタンを押下する。\\r\\n→倉庫権限が不足している旨のエラーメッセージが表示され、CSV出力ができないこと。\\r\\n\\r\\nとなっているが、どちらもエラーメッセージが表示されず④印刷および⑤CSV出力が出来てしまった\\r\\n\\r\\n以下の仕様書について、ご確認のほどよろしくお願いします。\\r\\n\\r\\nBox\\\\【TR】UC向けWMS構築プロジェクト\\\\483_総合テスト\\\\200_総合テスト仕様書\\\\410_結合残テスト\\r\\n総合テスト仕様書_結合残テスト_02_002.xlsx\\r\\n\\r\\n\\r\\n------\\r\\n\\r\\n### ２．期待結果\\r\\n\\r\\n　ログインユーザが出力対象の出荷指示ヘッダ.拠点倉庫コードの権限を持っているかチェックし\\r\\n　権限が無かったらエラーにする。\\r\\n\\r\\n　メッセージは「ME000409」を使用する。\\r\\n　メッセージは画面左上に表示する。\\r\\n\\r\\n------\\r\\n\\r\\n### ３．再現方法\\r\\n\\r\\n\\r\\n\\r\\n------\\r\\n\\r\\n### ４．原因\\r\\n\\r\\n　権限ない場合をチェックする処理が漏れたため\\r\\n\\r\\n------\\r\\n\\r\\n### ５．暫定対応\\r\\n\\r\\nなし\\r\\n\\r\\n------\\r\\n\\r\\n### ６．恒久対応\\r\\n\\r\\n権限がある場合とない場合をチェックする処理を追加し、GROUP BYを合わせて追加\\r\\n\\r\\n------\\r\\n\\r\\n### ７．特記事項\\r\\n\\r\\n　その他特記事項があれば記載（要更新）\\r\\n\\r\\n------", "spent_hours": 0.0, "custom_fields": [{"id": 19, "name": "発生フェーズ", "value": "26"}, {"id": 9, "name": "バグ混入フェーズ", "value": "4"}, {"id": 2, "name": "設計担当者", "value": ""}, {"id": 11, "name": "設計書修正要否", "value": ""}, {"id": 1, "name": "設計書修正対象", "value": ""}, {"id": 4, "name": "設計書修正内容", "value": ""}, {"id": 10, "name": "設計障害原因", "value": ""}, {"id": 15, "name": "設計書修正日", "value": ""}, {"id": 3, "name": "設計書レビュー担当者", "value": ""}, {"id": 22, "name": "設計書レビュー日", "value": ""}, {"id": 8, "name": "PG修正要否", "value": "2"}, {"id": 13, "name": "PG修正担当者", "value": ""}, {"id": 16, "name": "PG修正日", "value": ""}, {"id": 14, "name": "PG障害原因", "value": ""}, {"id": 12, "name": "PG修正対象", "value": ""}, {"id": 21, "name": "PGレビュー担当者", "value": ""}, {"id": 23, "name": "PGレビュー日", "value": ""}, {"id": 20, "name": "テスト環境リリース予定日", "value": "2023-10-18"}, {"id": 17, "name": "テスト環境リリース日", "value": "2023-10-18"}, {"id": 18, "name": "顧客リリース日", "value": "2023-10-19"}, {"id": 36, "name": "管理番号", "value": "Mantis_0000509"}, {"id": 50, "name": "水平展開", "value": null}], "fixed_version": {"id": 3, "name": "優先度：3"}, "estimated_hours": null, "total_spent_hours": 0.0, "total_estimated_hours": null}', '2026-05-05 09:21:16', '2026-05-05 09:21:35', '2026-05-05 09:21:35'),
	(2578, 1, 41, 15265, 2, 'バグ', 3, '終了(completed)', 1, '通常', 202, '斎藤 雄太朗(BP)', 9, '江田 隆志', '【新WMS】【外結－バグ】【SPIV00401_棚卸報告】【0000527】子倉庫権限しか持たないユーザで棚卸報告ができてしまう', '------\r\n\r\n### １．事象\r\n\r\n残_02_002#15\r\nユーザコード：TR000009\r\n④．親倉庫フィールドに、付与した子倉庫を持つ親倉庫を入力して検索したレコードを選択して、棚卸報告ボタンを押下する。\r\n→倉庫権限が不足している旨のエラーメッセージが表示され、棚卸報告ができないこと。\r\nとなっているが、エラーメッセージが表示されず、棚卸報告が実行されてしまう\r\n\r\n以下の仕様書について、ご確認のほどよろしくお願いします。\r\n\r\nBox\\【TR】UC向けWMS構築プロジェクト\\483_総合テスト\\200_総合テスト仕様書\\410_結合残テスト\r\n総合テスト仕様書_結合残テスト_02_002.xlsx\r\n\r\n\r\n------\r\n\r\n### ２．期待結果\r\n\r\n　権限のない子倉庫コードが存在した場合はエラーにする。\r\n　メッセージは「ME000409」を使用する。\r\n\r\n\r\n\r\n------\r\n\r\n### ３．再現方法\r\n\r\n\r\n\r\n------\r\n\r\n### ４．原因\r\n\r\n　事象が発生した原因を記載（要更新）\r\n\r\n------\r\n\r\n### ５．暫定対応\r\n\r\n　暫定対応があれば記載、なければ「なし」と記載（要更新）\r\n\r\n------\r\n\r\n### ６．恒久対応\r\n\r\n　恒久対応内容を記載（要更新）\r\n\r\n------\r\n\r\n### ７．特記事項\r\n\r\n　その他特記事項があれば記載（要更新）\r\n\r\n------', '2023-10-02', '2023-10-04', 100, NULL, 0, 0, '2023-10-02 08:39:38', '2023-10-04 07:19:44', '{"id": 15265, "author": {"id": 202, "name": "斎藤 雄太朗(BP)"}, "status": {"id": 3, "name": "終了(completed)", "is_closed": true}, "project": {"id": 8, "name": "トランコムWMS"}, "subject": "【新WMS】【外結－バグ】【SPIV00401_棚卸報告】【0000527】子倉庫権限しか持たないユーザで棚卸報告ができてしまう", "tracker": {"id": 2, "name": "バグ"}, "category": {"id": 43, "name": "SPIV00401_棚卸報告"}, "due_date": "2023-10-04", "priority": {"id": 1, "name": "通常"}, "closed_on": "2023-10-04T07:19:33Z", "created_on": "2023-10-02T08:39:38Z", "done_ratio": 100, "is_private": false, "start_date": "2023-10-02", "updated_on": "2023-10-04T07:19:44Z", "assigned_to": {"id": 9, "name": "江田 隆志"}, "description": "------\\r\\n\\r\\n### １．事象\\r\\n\\r\\n残_02_002#15\\r\\nユーザコード：TR000009\\r\\n④．親倉庫フィールドに、付与した子倉庫を持つ親倉庫を入力して検索したレコードを選択して、棚卸報告ボタンを押下する。\\r\\n→倉庫権限が不足している旨のエラーメッセージが表示され、棚卸報告ができないこと。\\r\\nとなっているが、エラーメッセージが表示されず、棚卸報告が実行されてしまう\\r\\n\\r\\n以下の仕様書について、ご確認のほどよろしくお願いします。\\r\\n\\r\\nBox\\\\【TR】UC向けWMS構築プロジェクト\\\\483_総合テスト\\\\200_総合テスト仕様書\\\\410_結合残テスト\\r\\n総合テスト仕様書_結合残テスト_02_002.xlsx\\r\\n\\r\\n\\r\\n------\\r\\n\\r\\n### ２．期待結果\\r\\n\\r\\n　権限のない子倉庫コードが存在した場合はエラーにする。\\r\\n　メッセージは「ME000409」を使用する。\\r\\n\\r\\n\\r\\n\\r\\n------\\r\\n\\r\\n### ３．再現方法\\r\\n\\r\\n\\r\\n\\r\\n------\\r\\n\\r\\n### ４．原因\\r\\n\\r\\n　事象が発生した原因を記載（要更新）\\r\\n\\r\\n------\\r\\n\\r\\n### ５．暫定対応\\r\\n\\r\\n　暫定対応があれば記載、なければ「なし」と記載（要更新）\\r\\n\\r\\n------\\r\\n\\r\\n### ６．恒久対応\\r\\n\\r\\n　恒久対応内容を記載（要更新）\\r\\n\\r\\n------\\r\\n\\r\\n### ７．特記事項\\r\\n\\r\\n　その他特記事項があれば記載（要更新）\\r\\n\\r\\n------", "spent_hours": 0.0, "custom_fields": [{"id": 19, "name": "発生フェーズ", "value": "26"}, {"id": 9, "name": "バグ混入フェーズ", "value": "4"}, {"id": 2, "name": "設計担当者", "value": ""}, {"id": 11, "name": "設計書修正要否", "value": ""}, {"id": 1, "name": "設計書修正対象", "value": ""}, {"id": 4, "name": "設計書修正内容", "value": ""}, {"id": 10, "name": "設計障害原因", "value": ""}, {"id": 15, "name": "設計書修正日", "value": ""}, {"id": 3, "name": "設計書レビュー担当者", "value": ""}, {"id": 22, "name": "設計書レビュー日", "value": ""}, {"id": 8, "name": "PG修正要否", "value": "2"}, {"id": 13, "name": "PG修正担当者", "value": ""}, {"id": 16, "name": "PG修正日", "value": ""}, {"id": 14, "name": "PG障害原因", "value": ""}, {"id": 12, "name": "PG修正対象", "value": ""}, {"id": 21, "name": "PGレビュー担当者", "value": ""}, {"id": 23, "name": "PGレビュー日", "value": ""}, {"id": 20, "name": "テスト環境リリース予定日", "value": "2023-10-03"}, {"id": 17, "name": "テスト環境リリース日", "value": "2023-10-03"}, {"id": 18, "name": "顧客リリース日", "value": "2023-10-04"}, {"id": 36, "name": "管理番号", "value": "Mantis_0000527"}, {"id": 50, "name": "水平展開", "value": null}], "fixed_version": {"id": 1, "name": "優先度：1"}, "estimated_hours": null, "total_spent_hours": 0.0, "total_estimated_hours": null}', '2026-05-05 09:21:16', '2026-05-05 09:21:35', '2026-05-05 09:21:35'),
	(2579, 1, 41, 15264, 2, 'バグ', 3, '終了(completed)', 1, '通常', 202, '斎藤 雄太朗(BP)', 9, '江田 隆志', '【新WMS】【外結－バグ】【SPOT00801_出荷状況照会・完了登録】【0000524】子倉庫権限しか持たないユーザで出荷完了を実行した際のエラーメッセージが想定結果と異なる', '------\r\n\r\n### １．事象\r\n\r\n残_02_002#11\r\nユーザコード：TR000009\r\n\r\n⑥．親倉庫フィールドに、付与した子倉庫を持つ親倉庫を入力して検索したレコードを選択して、出荷完了ボタンを押下する。\r\n→倉庫権限が不足している旨のエラーメッセージが表示され、出荷完了ができないこと。\r\n\r\nとなっているが、「対象データは他処理で更新されました。」というメッセージが表示される\r\n\r\n以下の仕様書について、ご確認のほどよろしくお願いします。\r\n\r\nBox\\【TR】UC向けWMS構築プロジェクト\\483_総合テスト\\200_総合テスト仕様書\\410_結合残テスト\r\n総合テスト仕様書_結合残テスト_02_002.xlsx\r\n\r\n\r\n------\r\n\r\n### ２．期待結果\r\n\r\n　処理対象データの便番号に紐づく出荷指示ヘッダの子倉庫を抽出してログインユーザに抽出した倉庫コードの権限が無い場合はエラーにする。\r\n　　条件は荷主コード、拠点倉庫コード(親倉庫コードで拠点倉庫マスタ検索)、便番号、出荷予定日、受払区分\r\n\r\n　メッセージは「ME000409」を使用する。\r\n　　表示位置は画面左上に１つ\r\n\r\n　参照\r\n　git\\trancom-wms-docs\\20.基本設計\\07_設計ポイント資料\\ユーザ別倉庫権限\\画面別倉庫権限整理.xlsx\r\n\r\n------\r\n\r\n### ３．再現方法\r\n\r\n\r\n\r\n------\r\n\r\n### ４．原因\r\n\r\n　正しくないメッセージをだしたため\r\n\r\n------\r\n\r\n### ５．暫定対応\r\n\r\n　なし\r\n\r\n------\r\n\r\n### ６．恒久対応\r\n\r\n　正しいメッセージを出すように修正しました。\r\n\r\n------\r\n\r\n### ７．特記事項\r\n\r\n　その他特記事項があれば記載（要更新）\r\n\r\n------', '2023-10-02', '2023-10-04', 100, NULL, 0, 0, '2023-10-02 08:35:43', '2023-10-05 11:28:53', '{"id": 15264, "author": {"id": 202, "name": "斎藤 雄太朗(BP)"}, "status": {"id": 3, "name": "終了(completed)", "is_closed": true}, "project": {"id": 8, "name": "トランコムWMS"}, "subject": "【新WMS】【外結－バグ】【SPOT00801_出荷状況照会・完了登録】【0000524】子倉庫権限しか持たないユーザで出荷完了を実行した際のエラーメッセージが想定結果と異なる", "tracker": {"id": 2, "name": "バグ"}, "category": {"id": 27, "name": "SPOT00801_出荷状況照会・完了登録"}, "due_date": "2023-10-04", "priority": {"id": 1, "name": "通常"}, "closed_on": "2023-10-05T11:28:53Z", "created_on": "2023-10-02T08:35:43Z", "done_ratio": 100, "is_private": false, "start_date": "2023-10-02", "updated_on": "2023-10-05T11:28:53Z", "assigned_to": {"id": 9, "name": "江田 隆志"}, "description": "------\\r\\n\\r\\n### １．事象\\r\\n\\r\\n残_02_002#11\\r\\nユーザコード：TR000009\\r\\n\\r\\n⑥．親倉庫フィールドに、付与した子倉庫を持つ親倉庫を入力して検索したレコードを選択して、出荷完了