	(3588, 1, 41, 12995, 1, '課題', 3, '終了(completed)', 1, '通常', 104, 'Pham ThanhHau', 9, '江田 隆志', '【確認事項】【SPCM00401_パスワード変更】排他チェックについて', '排他チェックについて聞きたいことがあります：\r\n　標準機能は排他チェックを実施してないことを認識しています。\r\n　今回排他チェックを追加すると思います。\r\n　今回は入力チェックの後で、開始確認POPUPを表示し、排他チェックを実施ています。\r\n　ですので、no13:間違うパスワードを確認するの時点で、その時点の現在パスワードをDBから取得すると認識で、もし他の人がパスワードを変更を行った場合は\r\n　　　→No13メッセージが表示し、排他チェックのメッセージを表示されないことが大丈夫でしょうか。\r\n![](image.png)\r\n', '2023-07-25', '2023-07-27', 100, NULL, 0, 0, '2023-07-25 00:57:37', '2023-07-25 02:43:34', '{"id": 12995, "author": {"id": 104, "name": "Pham ThanhHau"}, "status": {"id": 3, "name": "終了(completed)", "is_closed": true}, "project": {"id": 8, "name": "トランコムWMS"}, "subject": "【確認事項】【SPCM00401_パスワード変更】排他チェックについて", "tracker": {"id": 1, "name": "課題"}, "category": {"id": 57, "name": "SPCM00401_パスワード変更"}, "due_date": "2023-07-27", "priority": {"id": 1, "name": "通常"}, "closed_on": "2023-07-25T02:43:34Z", "created_on": "2023-07-25T00:57:37Z", "done_ratio": 100, "is_private": false, "start_date": "2023-07-25", "updated_on": "2023-07-25T02:43:34Z", "assigned_to": {"id": 9, "name": "江田 隆志"}, "description": "排他チェックについて聞きたいことがあります：\\r\\n　標準機能は排他チェックを実施してないことを認識しています。\\r\\n　今回排他チェックを追加すると思います。\\r\\n　今回は入力チェックの後で、開始確認POPUPを表示し、排他チェックを実施ています。\\r\\n　ですので、no13:間違うパスワードを確認するの時点で、その時点の現在パスワードをDBから取得すると認識で、もし他の人がパスワードを変更を行った場合は\\r\\n　　　→No13メッセージが表示し、排他チェックのメッセージを表示されないことが大丈夫でしょうか。\\r\\n![](image.png)\\r\\n", "spent_hours": 0.0, "custom_fields": [{"id": 19, "name": "発生フェーズ", "value": "32"}, {"id": 18, "name": "顧客リリース日", "value": null}, {"id": 36, "name": "管理番号", "value": ""}, {"id": 50, "name": "水平展開", "value": null}], "fixed_version": {"id": 4, "name": "優先度：4"}, "estimated_hours": null, "total_spent_hours": 0.0, "total_estimated_hours": null}', '2026-05-05 09:21:16', '2026-05-05 09:21:53', '2026-05-05 09:21:53'),
	(3589, 1, 41, 12993, 1, '課題', 3, '終了(completed)', 1, '通常', 230, '高 奫振', 9, '江田 隆志', '【確認事項】【SPOT00501_納品先マスタ】CSV出力ファイル定義書がないこと', 'CSV出力のファイル定義書がファイル設計書にはない状況ですのでご確認していただけますでしょうか。\r\n\r\n■パス\r\nC:\\work\\git\\トランコムdoc\\trancom-wms-docs\\20.基本設計\\06_ファイル設計', '2023-07-25', '2023-07-27', 100, NULL, 0, 0, '2023-07-25 00:17:35', '2023-07-26 11:24:55', '{"id": 12993, "author": {"id": 230, "name": "高 奫振"}, "status": {"id": 3, "name": "終了(completed)", "is_closed": true}, "project": {"id": 8, "name": "トランコムWMS"}, "subject": "【確認事項】【SPOT00501_納品先マスタ】CSV出力ファイル定義書がないこと", "tracker": {"id": 1, "name": "課題"}, "category": {"id": 48, "name": "SPMT00501_納品先マスタ"}, "due_date": "2023-07-27", "priority": {"id": 1, "name": "通常"}, "closed_on": "2023-07-26T11:24:55Z", "created_on": "2023-07-25T00:17:35Z", "done_ratio": 100, "is_private": false, "start_date": "2023-07-25", "updated_on": "2023-07-26T11:24:55Z", "assigned_to": {"id": 9, "name": "江田 隆志"}, "description": "CSV出力のファイル定義書がファイル設計書にはない状況ですのでご確認していただけますでしょうか。\\r\\n\\r\\n■パス\\r\\nC:\\\\work\\\\git\\\\トランコムdoc\\\\trancom-wms-docs\\\\20.基本設計\\\\06_ファイル設計", "spent_hours": 0.0, "custom_fields": [{"id": 19, "name": "発生フェーズ", "value": "25"}, {"id": 18, "name": "顧客リリース日", "value": null}, {"id": 36, "name": "管理番号", "value": ""}, {"id": 50, "name": "水平展開", "value": null}], "fixed_version": {"id": 4, "name": "優先度：4"}, "estimated_hours": null, "total_spent_hours": 0.0, "total_estimated_hours": null}', '2026-05-05 09:21:16', '2026-05-05 09:21:53', '2026-05-05 09:21:53'),
	(3590, 1, 41, 12992, 1, '課題', 3, '終了(completed)', 1, '通常', 223, 'NGUYEN DUC QUYNH ANH(BVN)', 9, '江田 隆志', '【SPMT00701】積付マスタ(インセンティブ) No.34のエラーチェック内容について', '\r\nエラーチェックシートのNo.34のチェック内容は「検索一覧に編集中のデータがある場合」として、クリアボタン押下の場合はエラーチェックを実施すると認識していますが、\r\n「クリアボタン」押下すること以外、「確定ボタン」押下する場合も、No.34のチェック内容として、エラーチェックを実施する必要でしょうか。\r\nご確認お願いたします。\r\n ', '2023-07-25', '2023-07-27', 100, NULL, 0, 0, '2023-07-24 10:01:54', '2023-09-04 04:25:26', '{"id": 12992, "author": {"id": 223, "name": "NGUYEN DUC QUYNH ANH(BVN)"}, "status": {"id": 3, "name": "終了(completed)", "is_closed": true}, "project": {"id": 8, "name": "トランコムWMS"}, "subject": "【SPMT00701】積付マスタ(インセンティブ) No.34のエラーチェック内容について", "tracker": {"id": 1, "name": "課題"}, "category": {"id": 50, "name": "SPMT00701_積付マスタ（インセンティブ）"}, "due_date": "2023-07-27", "priority": {"id": 1, "name": "通常"}, "closed_on": "2023-09-04T04:25:26Z", "created_on": "2023-07-24T10:01:54Z", "done_ratio": 100, "is_private": false, "start_date": "2023-07-25", "updated_on": "2023-09-04T04:25:26Z", "assigned_to": {"id": 9, "name": "江田 隆志"}, "description": "\\r\\nエラーチェックシートのNo.34のチェック内容は「検索一覧に編集中のデータがある場合」として、クリアボタン押下の場合はエラーチェックを実施すると認識していますが、\\r\\n「クリアボタン」押下すること以外、「確定ボタン」押下する場合も、No.34のチェック内容として、エラーチェックを実施する必要でしょうか。\\r\\nご確認お願いたします。\\r\\n ", "spent_hours": 0.0, "custom_fields": [{"id": 19, "name": "発生フェーズ", "value": "30"}, {"id": 18, "name": "顧客リリース日", "value": ""}, {"id": 36, "name": "管理番号", "value": ""}, {"id": 50, "name": "水平展開", "value": null}], "fixed_version": {"id": 4, "name": "優先度：4"}, "estimated_hours": null, "total_spent_hours": 0.0, "total_estimated_hours": null}', '2026-05-05 09:21:16', '2026-05-05 09:21:53', '2026-05-05 09:21:53');
INSERT INTO `issues` (`id`, `connection_id`, `project_id`, `redmine_issue_id`, `tracker_id`, `tracker_name`, `status_id`, `status_name`, `priority_id`, `priority_name`, `author_id`, `author_name`, `assignee_id`, `assignee_name`, `subject`, `description`, `start_date`, `due_date`, `done_ratio`, `estimated_hours`, `spent_hours`, `is_closed`, `redmine_created_on`, `redmine_updated_on`, `raw_data_json`, `last_synced_at`, `created_at`, `updated_at`) VALUES
	(3591, 1, 41, 12991, 1, '課題', 3, '終了(completed)', 1, '通常', 202, '斎藤 雄太朗(BP)', 9, '江田 隆志', '【確認事項】【SPOT00401_在庫引当・取消】ユーザ別倉庫権限対応による画面表示', '別子倉庫同一便の場合\r\n例えば下記のようなマスタ設定の場合でも\r\n権限以外のデータ(4003)は表示・処理しますか。\r\n\r\n倉庫権限マスタ\r\n\r\n|子倉庫|親倉庫|親子区分|\r\n|--|--|--|\r\n|4001|4099|0|\r\n|4002|4099|0|\r\n\r\n表示\r\n\r\n|子倉庫|子倉庫名|受払区分|便番号|便名称|便ステータス|\r\n|--|--|--|--|--|--|\r\n|4001|中日本第3DC|巡回|1001|巡回1|全量未引|\r\n|4002|中日併設DC|巡回|1001|巡回1|全量未引|\r\n|4003|中日本第2DC|巡回|1001|巡回1|全量未引|\r\n\r\n', '2023-07-24', '2023-08-02', 100, NULL, 0, 0, '2023-07-24 08:44:53', '2023-08-03 13:06:07', '{"id": 12991, "author": {"id": 202, "name": "斎藤 雄太朗(BP)"}, "status": {"id": 3, "name": "終了(completed)", "is_closed": true}, "project": {"id": 8, "name": "トランコムWMS"}, "subject": "【確認事項】【SPOT00401_在庫引当・取消】ユーザ別倉庫権限対応による画面表示", "tracker": {"id": 1, "name": "課題"}, "category": {"id": 23, "name": "SPOT00401_在庫引当・取消"}, "due_date": "2023-08-02", "priority": {"id": 1, "name": "通常"}, "closed_on": "2023-08-03T13:06:07Z", "created_on": "2023-07-24T08:44:53Z", "done_ratio": 100, "is_private": false, "start_date": "2023-07-24", "updated_on": "2023-08-03T13:06:07Z", "assigned_to": {"id": 9, "name": "江田 隆志"}, "description": "別子倉庫同一便の場合\\r\\n例えば下記のようなマスタ設定の場合でも\\r\\n権限以外のデータ(4003)は表示・処理しますか。\\r\\n\\r\\n倉庫権限マスタ\\r\\n\\r\\n|子倉庫|親倉庫|親子区分|\\r\\n|--|--|--|\\r\\n|4001|4099|0|\\r\\n|4002|4099|0|\\r\\n\\r\\n表示\\r\\n\\r\\n|子倉庫|子倉庫名|受払区分|便番号|便名称|便ステータス|\\r\\n|--|--|--|--|--|--|\\r\\n|4001|中日本第3DC|巡回|1001|巡回1|全量未引|\\r\\n|4002|中日併設DC|巡回|1001|巡回1|全量未引|\\r\\n|4003|中日本第2DC|巡回|1001|巡回1|全量未引|\\r\\n\\r\\n", "spent_hours": 0.0, "custom_fields": [{"id": 19, "name": "発生フェーズ", "value": "25"}, {"id": 18, "name": "顧客リリース日", "value": ""}, {"id": 36, "name": "管理番号", "value": ""}, {"id": 50, "name": "水平展開", "value": null}], "fixed_version": {"id": 2, "name": "優先度：2"}, "estimated_hours": null, "total_spent_hours": 0.0, "total_estimated_hours": null}', '2026-05-05 09:21:16', '2026-05-05 09:21:53', '2026-05-05 09:21:53'),
	(3592, 1, 41, 12977, 1, '課題', 3, '終了(completed)', 1, '通常', 9, '江田 隆志', 9, '江田 隆志', '【課題】【帳票出力全般】出力前・出力後のメッセージ出力について', 'CSV・帳票の出力時のメッセージについて教えてください。\r\n一部の機能（SPIV00301_棚卸実績集計）では、出力前・出力後に以下のメッセージが表示されています。\r\n・出力前　「出力します。よろしいですか？」\r\n・出力後　「出力しました。」\r\n\r\n\r\n![](image.png)\r\n\r\n\r\n対して、「SPOT00101_受領書回収チェック表出力」は記載がないです。', '2023-07-24', '2023-07-28', 100, NULL, 0, 0, '2023-07-24 06:35:51', '2023-10-25 12:05:40', '{"id": 12977, "author": {"id": 9, "name": "江田 隆志"}, "status": {"id": 3, "name": "終了(completed)", "is_closed": true}, "project": {"id": 8, "name": "トランコムWMS"}, "subject": "【課題】【帳票出力全般】出力前・出力後のメッセージ出力について", "tracker": {"id": 1, "name": "課題"}, "category": {"id": 62, "name": "COMMON_共通"}, "due_date": "2023-07-28", "priority": {"id": 1, "name": "通常"}, "closed_on": "2023-10-25T12:05:40Z", "created_on": "2023-07-24T06:35:51Z", "done_ratio": 100, "is_private": false, "start_date": "2023-07-24", "updated_on": "2023-10-25T12:05:40Z", "assigned_to": {"id": 9, "name": "江田 隆志"}, "description": "CSV・帳票の出力時のメッセージについて教えてください。\\r\\n一部の機能（SPIV00301_棚卸実績集計）では、出力前・出力後に以下のメッセージが表示されています。\\r\\n・出力前　「出力します。よろしいですか？」\\r\\n・出力後　「出力しました。」\\r\\n\\r\\n\\r\\n![](image.png)\\r\\n\\r\\n\\r\\n対して、「SPOT00101_受領書回収チェック表出力」は記載がないです。", "spent_hours": 0.0, "custom_fields": [{"id": 19, "name": "発生フェーズ", "value": "25"}, {"id": 18, "name": "顧客リリース日", "value": null}, {"id": 36, "name": "管理番号", "value": ""}, {"id": 50, "name": "水平展開", "value": null}], "fixed_version": {"id": 3, "name": "優先度：3"}, "estimated_hours": null, "total_spent_hours": 0.0, "total_estimated_hours": null}', '2026-05-05 09:21:16', '2026-05-05 09:21:53', '2026-05-05 09:21:53'),
	(3593, 1, 41, 12976, 2, 'バグ', 3, '終了(completed)', 1, '通常', 203, '沈 闖(BP)', 9, '江田 隆志', '【新WMS】【結合－バグ】【SPOT01001_出荷トレース取込】エラーチェック処理のロジックが不正', '------\r\n\r\n### １．事象\r\n\r\n　「パレット」「ケース」「出荷実績数」のいずれかが１以上で設定されているかチェックはすべて１以上で設定することになっている\r\n\r\n------\r\n\r\n### ２．期待結果\r\n\r\n　いずれかが１以上で設定されているかチェックを行う\r\n\r\n\r\n------\r\n\r\n### ３．再現方法\r\n\r\n　\r\n「パレット」「ケース」「出荷実績数」のいずれか「0」を設定して取込を行う\r\n\r\n------\r\n\r\n### ４．原因\r\n\r\n　設計書に認識不足があったため、\r\n\r\n------\r\n\r\n### ５．暫定対応\r\n\r\n　なし\r\n\r\n------\r\n\r\n### ６．恒久対応\r\n\r\n　すべてではなく、いずれか１以上で設定されてない場合、エラーチェックに引っかかるように修正\r\n\r\n------\r\n\r\n### ７．特記事項\r\n\r\n　なし\r\n\r\n------', '2023-07-24', '2023-07-26', 100, NULL, 0, 0, '2023-07-24 05:53:18', '2023-07-25 10:26:58', '{"id": 12976, "author": {"id": 203, "name": "沈 闖(BP)"}, "status": {"id": 3, "name": "終了(completed)", "is_closed": true}, "project": {"id": 8, "name": "トランコムWMS"}, "subject": "【新WMS】【結合－バグ】【SPOT01001_出荷トレース取込】エラーチェック処理のロジックが不正", "tracker": {"id": 2, "name": "バグ"}, "category": {"id": 29, "name": "SPOT01001_出荷トレース取込"}, "due_date": "2023-07-26", "priority": {"id": 1, "name": "通常"}, "closed_on": "2023-07-25T10:26:58Z", "created_on": "2023-07-24T05:53:18Z", "done_ratio": 100, "is_private": false, "start_date": "2023-07-24", "updated_on": "2023-07-25T10:26:58Z", "assigned_to": {"id": 9, "name": "江田 隆志"}, "description": "------\\r\\n\\r\\n### １．事象\\r\\n\\r\\n　「パレット」「ケース」「出荷実績数」のいずれかが１以上で設定されているかチェックはすべて１以上で設定することになっている\\r\\n\\r\\n------\\r\\n\\r\\n### ２．期待結果\\r\\n\\r\\n　いずれかが１以上で設定されているかチェックを行う\\r\\n\\r\\n\\r\\n------\\r\\n\\r\\n### ３．再現方法\\r\\n\\r\\n　\\r\\n「パレット」「ケース」「出荷実績数」のいずれか「0」を設定して取込を行う\\r\\n\\r\\n------\\r\\n\\r\\n### ４．原因\\r\\n\\r\\n　設計書に認識不足があったため、\\r\\n\\r\\n------\\r\\n\\r\\n### ５．暫定対応\\r\\n\\r\\n　なし\\r\\n\\r\\n------\\r\\n\\r\\n### ６．恒久対応\\r\\n\\r\\n　すべてではなく、いずれか１以上で設定されてない場合、エラーチェックに引っかかるように修正\\r\\n\\r\\n------\\r\\n\\r\\n### ７．特記事項\\r\\n\\r\\n　なし\\r\\n\\r\\n------", "spent_hours": 0.0, "custom_fields": [{"id": 19, "name": "発生フェーズ", "value": "26"}, {"id": 9, "name": "バグ混入フェーズ", "value": "6"}, {"id": 2, "name": "設計担当者", "value": ""}, {"id": 11, "name": "設計書修正要否", "value": ""}, {"id": 1, "name": "設計書修正対象", "value": ""}, {"id": 4, "name": "設計書修正内容", "value": ""}, {"id": 10, "name": "設計障害原因", "value": ""}, {"id": 15, "name": "設計書修正日", "value": ""}, {"id": 3, "name": "設計書レビュー担当者", "value": ""}, {"id": 22, "name": "設計書レビュー日", "value": ""}, {"id": 8, "name": "PG修正要否", "value": "2"}, {"id": 13, "name": "PG修正担当者", "value": ""}, {"id": 16, "name": "PG修正日", "value": ""}, {"id": 14, "name": "PG障害原因", "value": ""}, {"id": 12, "name": "PG修正対象", "value": ""}, {"id": 21, "name": "PGレビュー担当者", "value": ""}, {"id": 23, "name": "PGレビュー日", "value": ""}, {"id": 20, "name": "テスト環境リリース予定日", "value": "2023-07-24"}, {"id": 17, "name": "テスト環境リリース日", "value": ""}, {"id": 18, "name": "顧客リリース日", "value": ""}, {"id": 36, "name": "管理番号", "value": ""}, {"id": 50, "name": "水平展開", "value": null}], "fixed_version": {"id": 3, "name": "優先度：3"}, "estimated_hours": null, "total_spent_hours": 0.0, "total_estimated_hours": null}', '2026-05-05 09:21:16', '2026-05-05 09:21:53', '2026-05-05 09:21:53'),
	(3594, 1, 41, 12975, 1, '課題', 3, '終了(completed)', 1, '通常', 135, '丹野 亜美(BP)', 9, '江田 隆志', '【確認事項】【出荷トレース関連】納品先コードに入る値について　', '納品先コードには、受払区分によって仕入先・配送先・子倉庫マスタの何れかの値が入る認識です。\r\n\r\n納品先コードについて、下記2質問させてください。\r\n①出荷トレース取込を実施する際は、必ず6桁までの数値でしょうか。出荷トレース取込の基本設計書に、納品先コードは6桁で6桁に満たない場合は頭0埋めの記載があったので、英字の場合の頭0埋めはおかしいなと思いました。\r\n（例；AAAA → 00AAAAになる）\r\n②出荷トレース取込は、受払区分：支線出荷 or 輸出でしか使用しないでしょうか。\r\n　①と同様の理由ですが、幹線・巡回の場合、拠点倉庫コードが入るので4桁になりますが、前0が入ってしまい取込ができませんでした。（例：3302 → 003302になる）\r\n　この機能で使用する受払区分が決まっていたら教えてください。\r\n\r\n\r\n', '2023-07-24', '2023-07-26', 100, NULL, 0, 0, '2023-07-24 05:32:23', '2023-07-25 10:25:14', '{"id": 12975, "author": {"id": 135, "name": "丹野 亜美(BP)"}, "status": {"id": 3, "name": "終了(completed)", "is_closed": true}, "project": {"id": 8, "name": "トランコムWMS"}, "subject": "【確認事項】【出荷トレース関連】納品先コードに入る値について　", "tracker": {"id": 1, "name": "課題"}, "category": {"id": 29, "name": "SPOT01001_出荷トレース取込"}, "due_date": "2023-07-26", "priority": {"id": 1, "name": "通常"}, "closed_on": "2023-07-25T10:25:14Z", "created_on": "2023-07-24T05:32:23Z", "done_ratio": 100, "is_private": false, "start_date": "2023-07-24", "updated_on": "2023-07-25T10:25:14Z", "assigned_to": {"id": 9, "name": "江田 隆志"}, "description": "納品先コードには、受払区分によって仕入先・配送先・子倉庫マスタの何れかの値が入る認識です。\\r\\n\\r\\n納品先コードについて、下記2質問させてください。\\r\\n①出荷トレース取込を実施する際は、必ず6桁までの数値でしょうか。出荷トレース取込の基本設計書に、納品先コードは6桁で6桁に満たない場合は頭0埋めの記載があったので、英字の場合の頭0埋めはおかしいなと思いました。\\r\\n（例；AAAA → 00AAAAになる）\\r\\n②出荷トレース取込は、受払区分：支線出荷 or 輸出でしか使用しないでしょうか。\\r\\n　①と同様の理由ですが、幹線・巡回の場合、拠点倉庫コードが入るので4桁になりますが、前0が入ってしまい取込ができませんでした。（例：3302 → 003302になる）\\r\\n　この機能で使用する受払区分が決まっていたら教えてください。\\r\\n\\r\\n\\r\\n", "spent_hours": 0.0, "custom_fields": [{"id": 19, "name": "発生フェーズ", "value": "25"}, {"id": 18, "name": "顧客リリース日", "value": null}, {"id": 36, "name": "管理番号", "value": ""}, {"id": 50, "name": "水平展開", "value": null}], "fixed_version": {"id": 3, "name": "優先度：3"}, "estimated_hours": null, "total_spent_hours": 0.0, "total_estimated_hours": null}', '2026-05-05 09:21:16', '2026-05-05 09:21:53', '2026-05-05 09:21:53'),
	(3595, 1, 41, 12974, 2, 'バグ', 3, '終了(completed)', 1, '通常', 135, '丹野 亜美(BP)', 9, '江田 隆志', '【新WMS】【結合－バグ】【在庫照会】【xxxxxx】GROUP BYに同じ項目を2回記載している', '------\r\n\r\n### １．事象\r\n　「集計：子倉庫・商品」のとき、在庫.商品コードを2回記載している\r\n\r\n       strSql.append("  GROUP BY ");\r\n       strSql.append("    TST010.BRNCHCD ");\r\n       strSql.append("    , TMT120.BRNCHRNM ");\r\n       strSql.append("    , TST010.ITEMCD ");\r\n       strSql.append("    , TMT090.ITEMRNM ");\r\n       strSql.append("    , TST010.QLTYCD ");\r\n　　   strSql.append("    , TMT050.DATARNM ");\r\n       strSql.append("    , TST010.ITEMCD ");　←ここ\r\n\r\n\r\n\r\n------\r\n\r\n### ２．期待結果\r\n\r\n　不要な記載が削除されること\r\n\r\n\r\n\r\n------\r\n\r\n### ３．再現方法\r\n\r\n　１の補足として再現方法があれば手順を記載（要更新）\r\n\r\n\r\n------\r\n\r\n### ４．原因\r\n\r\n　GROUP BY項目の確認漏れ\r\n\r\n------\r\n\r\n### ５．暫定対応\r\n\r\n　なし\r\n\r\n------\r\n\r\n### ６．恒久対応\r\n\r\n　不要な項目の削除\r\n\r\n------\r\n\r\n### ７．特記事項\r\n\r\n　その他特記事項があれば記載（要更新）\r\n\r\n------', '2023-07-24', '2023-07-26', 100, NULL, 0, 0, '2023-07-24 04:33:51', '2023-07-25 06:15:12', '{"id": 12974, "author": {"id": 135, "name": "丹野 亜美(BP)"}, "status": {"id": 3, "name": "終了(completed)", "is_closed": true}, "project": {"id": 8, "name": "トランコムWMS"}, "subject": "【新WMS】【結合－バグ】【在庫照会】【xxxxxx】GROUP BYに同じ項目を2回記載している", "tracker": {"id": 2, "name": "バグ"}, "category": {"id": 38, "name": "SPVW00101_在庫照会"}, "due_date": "2023-07-26", "priority": {"id": 1, "name": "通常"}, "closed_on": "2023-07-25T06:15:12Z", "created_on": "2023-07-24T04:33:51Z", "done_ratio": 100, "is_private": false, "start_date": "2023-07-24", "updated_on": "2023-07-25T06:15:12Z", "assigned_to": {"id": 9, "name": "江田 隆志"}, "description": "------\\r\\n\\r\\n### １．事象\\r\\n　「集計：子倉庫・商品」のとき、在庫.商品コードを2回記載している\\r\\n\\r\\n       strSql.append(\\"  GROUP BY \\");\\r\\n       strSql.append(\\"    TST010.BRNCHCD \\");\\r\\n       strSql.append(\\"    , TMT120.BRNCHRNM \\");\\r\\n       strSql.append(\\"    , TST010.ITEMCD \\");\\r\\n       strSql.append(\\"    , TMT090.ITEMRNM \\");\\r\\n       strSql.append(\\"    , TST010.QLTYCD \\");\\r\\n　　   strSql.append(\\"    , TMT050.DATARNM \\");\\r\\n       strSql.append(\\"    , TST010.ITEMCD \\");　←ここ\\r\\n\\r\\n\\r\\n\\r\\n------\\r\\n\\r\\n### ２．期待結果\\r\\n\\r\\n　不要な記載が削除されること\\r\\n\\r\\n\\r\\n\\r\\n------\\r\\n\\r\\n### ３．再現方法\\r\\n\\r\\n　１の補足として再現方法があれば手順を記載（要更新）\\r\\n\\r\\n\\r\\n------\\r\\n\\r\\n### ４．原因\\r\\n\\r\\n　GROUP BY項目の確認漏れ\\r\\n\\r\\n------\\r\\n\\r\\n### ５．暫定対応\\r\\n\\r\\n　なし\\r\\n\\r\\n------\\r\\n\\r\\n### ６．恒久対応\\r\\n\\r\\n　不要な項目の削除\\r\\n\\r\\n------\\r\\n\\r\\n### ７．特記事項\\r\\n\\r\\n　その他特記事項があれば記載（要更新）\\r\\n\\r\\n------", "spent_hours": 0.0, "custom_fields": [{"id": 19, "name": "発生フェーズ", "value": "25"}, {"id": 9, "name": "バグ混入フェーズ", "value": "6"}, {"id": 2, "name": "設計担当者", "value": ""}, {"id": 11, "name": "設計書修正要否", "value": ""}, {"id": 1, "name": "設計書修正対象", "value": ""}, {"id": 4, "name": "設計書修正内容", "value": ""}, {"id": 10, "name": "設計障害原因", "value": ""}, {"id": 15, "name": "設計書修正日", "value": ""}, {"id": 3, "name": "設計書レビュー担当者", "value": ""}, {"id": 22, "name": "設計書レビュー日", "value": ""}, {"id": 8, "name": "PG修正要否", "value": "2"}, {"id": 13, "name": "PG修正担当者", "value": ""}, {"id": 16, "name": "PG修正日", "value": ""}, {"id": 14, "name": "PG障害原因", "value": ""}, {"id": 12, "name": "PG修正対象", "value": ""}, {"id": 21, "name": "PGレビュー担当者", "value": ""}, {"id": 23, "name": "PGレビュー日", "value": ""}, {"id": 20, "name": "テスト環境リリース予定日", "value": ""}, {"id": 17, "name": "テスト環境リリース日", "value": ""}, {"id": 18, "name": "顧客リリース日", "value": ""}, {"id": 36, "name": "管理番号", "value": ""}, {"id": 50, "name": "水平展開", "value": null}], "fixed_version": {"id": 3, "name": "優先度：3"}, "estimated_hours": null, "total_spent_hours": 0.0, "total_estimated_hours": null}', '2026-05-05 09:21:16', '2026-05-05 09:21:53', '2026-05-05 09:21:53'),
	(3596, 1, 41, 12973, 1, '課題', 3, '終了(completed)', 1, '通常', 202, '斎藤 雄太朗(BP)', 9, '江田 隆志', '【確認事項】【SPOT01001_出荷トレース取込】ユーザ別倉庫権限対応によるエラーチェック', '出荷トレース取込では取込CSVに子倉庫コードはありませんが\r\n出荷伝票番号で子倉庫を引いてエラーチェックするのでしょうか。\r\n', '2023-07-24', '2023-08-04', 100, NULL, 0, 0, '2023-07-24 04:23:23', '2023-08-14 04:29:38', '{"id": 12973, "author": {"id": 202, "name": "斎藤 雄太朗(BP)"}, "status": {"id": 3, "name": "終了(completed)", "is_closed": true}, "project": {"id": 8, "name": "トランコムWMS"}, "subject": "【確認事項】【SPOT01001_出荷トレース取込】ユーザ別倉庫権限対応によるエラーチェック", "tracker": {"id": 1, "name": "課題"}, "category": {"id": 29, "name": "SPOT01001_出荷トレース取込"}, "due_date": "2023-08-04", "priority": {"id": 1, "name": "通常"}, "closed_on": "2023-08-14T04:29:38Z", "created_on": "2023-07-24T04:23:23Z", "done_ratio": 100, "is_private": false, "start_date": "2023-07-24", "updated_on": "2023-08-14T04:29:38Z", "assigned_to": {"id": 9, "name": "江田 隆志"}, "description": "出荷トレース取込では取込CSVに子倉庫コードはありませんが\\r\\n出荷伝票番号で子倉庫を引いてエラーチェックするのでしょうか。\\r\\n", "spent_hours": 0.0, "custom_fields": [{"id": 19, "name": "発生フェーズ", "value": "25"}, {"id": 18, "name": "顧客リリース日", "value": "2023-08-16"}, {"id": 36, "name": "管理番号", "value": ""}, {"id": 50, "name": "水平展開", "value": null}], "fixed_version": {"id": 3, "name": "優先度：3"}, "estimated_hours": null, "total_spent_hours": 0.0, "total_estimated_hours": null}', '2026-05-05 09:21:16', '2026-05-05 09:21:53', '2026-05-05 09:21:53'),
	(3597, 1, 41, 12972, 1, '課題', 3, '終了(completed)', 1, '通常', 202, '斎藤 雄太朗(BP)', 9, '江田 隆志', '【確認事項】【SPIN00101_入荷予定取込】ユーザ別倉庫権限対応によるエラーチェック', '入荷予定取込では取込CSVに子倉庫コードを入力しているので\r\nユーザによっては取込時に権限のない子倉庫コードはエラーになる認識です。\r\n\r\n認識相違なければ設計書にエラーチェックとエラーメッセージの追加をお願いします。', '2023-07-24', '2023-08-04', 100, NULL, 0, 0, '2023-07-24 04:21:29', '2023-08-10 09:34:07', '{"id": 12972, "author": {"id": 202, "name": "斎藤 雄太朗(BP)"}, "status": {"id": 3, "name": "終了(completed)", "is_closed": true}, "project": {"id": 8, "name": "トランコムWMS"}, "subject": "【確認事項】【SPIN00101_入荷予定取込】ユーザ別倉庫権限対応によるエラーチェック", "tracker": {"id": 1, "name": "課題"}, "category": {"id": 19, "name": "SPIN00101_入荷予定取込"}, "due_date": "2023-08-04", "priority": {"id": 1, "name": "通常"}, "closed_on": "2023-08-10T09:34:07Z", "created_on": "2023-07-24T04:21:29Z", "done_ratio": 100, "is_private": false, "start_date": "2023-07-24", "updated_on": "2023-08-10T09:34:07Z", "assigned_to": {"id": 9, "name": "江田 隆志"}, "description": "入荷予定取込では取込CSVに子倉庫コードを入力しているので\\r\\nユーザによっては取込時に権限のない子倉庫コードはエラーになる認識です。\\r\\n\\r\\n認識相違なければ設計書にエラーチェックとエラーメッセージの追加をお願いします。", "spent_hours": 0.0, "custom_fields": [{"id": 19, "name": "発生フェーズ", "value": "25"}, {"id": 18, "name": "顧客リリース日", "value": "2023-08-10"}, {"id": 36, "name": "管理番号", "value": ""}, {"id": 50, "name": "水平展開", "value": null}], "fixed_version": {"id": 1, "name": "優先度：1"}, "estimated_hours": null, "total_spent_hours": 0.0, "total_estimated_hours": null}', '2026-05-05 09:21:16', '2026-05-05 09:21:53', '2026-05-05 09:21:53'),
	(3598, 1, 41, 12971, 2, 'バグ', 3, '終了(completed)', 1, '通常', 202, '斎藤 雄太朗(BP)', 9, '江田 隆志', '【新WMS】【結合－バグ】【SPOT00201_OEM返品登録】【xxxxxx】新規登録時、出荷予定日がCURDATE()', '------\r\n\r\n### １．事象\r\n\r\n　新規登録時、出荷予定日が業務日付ではなくCURDATE()になっている\r\n\r\n\r\n------\r\n\r\n### ２．期待結果\r\n\r\n　業務日付(日付マスタで日付識別コード\'01\') \r\n　修正版の設計書を添付しました。\r\n\r\n\r\n------\r\n\r\n### ３．再現方法\r\n\r\n　\r\n\r\n\r\n------\r\n\r\n### ４．原因\r\n\r\n　設計不備\r\n\r\n------\r\n\r\n### ５．暫定対応\r\n\r\n　なし\r\n------\r\n\r\n### ６．恒久対応\r\n\r\n　業務日付を変更しました。\r\n------\r\n\r\n### ７．特記事項\r\n\r\n　その他特記事項があれば記載（要更新）\r\n\r\n------', '2023-07-24', '2023-07-26', 100, NULL, 0, 0, '2023-07-24 04:18:04', '2023-07-27 07:40:55', '{"id": 12971, "author": {"id": 202, "name": "斎藤 雄太朗(BP)"}, "status": {"id": 3, "name": "終了(completed)", "is_closed": true}, "project": {"id": 8, "name": "トランコムWMS"}, "subject": "【新WMS】【結合－バグ】【SPOT00201_OEM返品登録】【xxxxxx】新規登録時、出荷予定日がCURDATE()", "tracker": {"id": 2, "name": "バグ"}, "category": {"id": 21, "name": "SPOT00201_OEM返品登録"}, "due_date": "2023-07-26", "priority": {"id": 1, "name": "通常"}, "closed_on": "2023-07-27T07:40:55Z", "created_on": "2023-07-24T04:18:04Z", "done_ratio": 100, "is_private": false, "start_date": "2023-07-24", "updated_on": "2023-07-27T07:40:55Z", "assigned_to": {"id": 9, "name": "江田 隆志"}, "description": "------\\r\\n\\r\\n### １．事象\\r\\n\\r\\n　新規登録時、出荷予定日が業務日付ではなくCURDATE()になっている\\r\\n\\r\\n\\r\\n------\\r\\n\\r\\n### ２．期待結果\\r\\n\\r\\n　業務日付(日付マスタで日付識別コード\'01\') \\r\\n　修正版の設計書を添付しました。\\r\\n\\r\\n\\r\\n------\\r\\n\\r\\n### ３．再現方法\\r\\n\\r\\n　\\r\\n\\r\\n\\r\\n------\\r\\n\\r\\n### ４．原因\\r\\n\\r\\n　設計不備\\r\\n\\r\\n------\\r\\n\\r\\n### ５．暫定対応\\r\\n\\r\\n　なし\\r\\n------\\r\\n\\r\\n### ６．恒久対応\\r\\n\\r\\n　業務日付を変更しました。\\r\\n------\\r\\n\\r\\n### ７．特記事項\\r\\n\\r\\n　その他特記事項があれば記載（要更新）\\r\\n\\r\\n------", "spent_hours": 0.0, "custom_fields": [{"id": 19, "name": "発生フェーズ", "value": "25"}, {"id": 9, "name": "バグ混入フェーズ", "value": "4"}, {"id": 2, "name": "設計担当者", "value": ""}, {"id": 11, "name": "設計書修正要否", "val