	(3817, 1, 41, 11430, 2, 'バグ', 3, '終了(completed)', 1, '通常', 202, '斎藤 雄太朗(BP)', 9, '江田 隆志', '【新WMS】【結合－バグ】【SPOT00701_出荷・出庫検品完了登録】【xxxxxx】要因コードが同一伝票・商品のレコードすべてに登録されない', '------\r\n\r\n### １．事象\r\n\r\n　１．子画面を表示して１行目の欠品数に2を入力、要因コードは１つ目を選択して保存→確定\r\n　２．子画面を表示して１行目の欠品数に0を入力、２行目の欠品数に2を入力、要因コードは２つ目を選択して保存→確定\r\n　３．欠品総数が2ではなく4になる\r\n\r\n\r\n------\r\n\r\n### ２．期待結果\r\n\r\n　要因コードが同一伝票・商品のレコードすべてに登録される\r\n\r\n![](1.png)\r\n\r\n保存ボタン押下時\r\n同一伝票・同一商品で要因コードの設定が必要な対象行は保存データを作成してください。\r\n\r\n\r\n\r\n------\r\n\r\n### ３．再現方法\r\n\r\nINSERT INTO `tot010_sts` VALUES (\'DEMO0001\',\'3302\',\'5520230705\',\'1\',\'1\',\'1\',\'0\',\'0\',\'0\',\'0\',\'0\',\'0\',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,\'9999\',\'2023-07-05 10:17:42\',\'FPOT0020\',\'9999\',\'2023-07-07 15:49:20\',\'FPOT0070\');\r\nINSERT INTO `tot020_ordhed` VALUES (\'DEMO0001\',\'3302\',\'5520230705\',\'9900\',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,\'0\',NULL,NULL,NULL,NULL,0,NULL,NULL,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,\'2023-07-05\',NULL,NULL,NULL,\'00000000000\',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,\'DEMO0001\',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,\'9999\',NULL,\'55\',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,\'9999\',\'2023-07-05 10:17:42\',\'FPOT0020\',\'9999\',\'2023-07-05 10:17:42\',\'FPOT0020\');\r\nINSERT INTO `tot040_orddtl` VALUES (\'DEMO0001\',\'3302\',\'5520230705\',1,\'00010009\',NULL,\'51\',NULL,NULL,\'2023/05\',NULL,NULL,NULL,NULL,NULL,10000,0,0,10000,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,0,0,0,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,\'9999\',\'2023-07-05 10:17:42\',\'FPOT0020\',\'9999\',\'2023-0