	(4117, 1, 41, 9391, 1, '課題', 3, '終了(completed)', 1, '通常', 32, 'Paudel Pawan', 9, '江田 隆志', '【SPOT01601_送り状発行】CSVボタンを押した時のSQL《内部結合7》について', '《内部結合7》の出荷指示明細は以下のサブクエリ：出荷指示明細のことで合っていますか。\r\n![](image1.png)\r\n', '2023-06-09', '2023-06-13', 100, NULL, 0, 0, '2023-06-09 09:40:15', '2023-06-28 05:25:06', '{"id": 9391, "author": {"id": 32, "name": "Paudel Pawan"}, "status": {"id": 3, "name": "終了(completed)", "is_closed": true}, "project": {"id": 8, "name": "トランコムWMS"}, "subject": "【SPOT01601_送り状発行】CSVボタンを押した時のSQL《内部結合7》について", "tracker": {"id": 1, "name": "課題"}, "category": {"id": 33, "name": "SPOT01601_送り状発行"}, "due_date": "2023-06-13", "priority": {"id": 1, "name": "通常"}, "closed_on": "2023-06-28T05:25:06Z", "created_on": "2023-06-09T09:40:15Z", "done_ratio": 100, "is_private": false, "start_date": "2023-06-09", "updated_on": "2023-06-28T05:25:06Z", "assigned_to": {"id": 9, "name": "江田 隆志"}, "description": "《内部結合7》の出荷指示明細は以下のサブクエリ：出荷指示明細のことで合っていますか。\\r\\n![](image1.png)\\r\\n", "spent_hours": 0.0, "custom_fields": [{"id": 19, "name": "発生フェーズ", "value": "31"}, {"id": 18, "name": "顧客リリース日", "value": null}, {"id": 36, "name": "管理番号", "value": ""}, {"id": 50, "name": "水平展開", "value": null}], "fixed_version": {"id": 3, "name": "優先度：3"}, "estimated_hours": null, "total_spent_hours": 0.0, "total_estimated_hours": null}', '2026-05-05 09:21:16', '2026-05-05 09:22:01', '2026-05-05 09:22:01'),
	(4118, 1, 41, 9387, 1, '課題', 3, '終了(completed)', 1, '通常', 31, '朴 鍾昊', 9, '江田 隆志', '【確認事項】【在庫受払照会】画面レイアウトの項目、SELECTのJOIN条件の質問、SELECTのWHERE条件の質問', '**１．画面レイアウトの「受注番号」、「購買伝票番号」、「在庫転送オーダー番号」ですが、「画面項目説明シート」に説明がないので確認させてください。**\r\n![](画面項目疑問点.jpg)\r\n\r\n**２．「処理概要シート」の125行目と132行目ですが、**\r\n125行目：「在庫受払履歴.仕入先コード⇒配送先コード」\r\n132行目：「在庫受払履歴.倉庫コード⇒配送先コード」ではないのでしょうか。\r\n\r\n![](evi1.jpg)\r\n![](evi2.jpg)\r\n![](evi3.jpg)\r\n\r\n**３．在庫受払テーブルには拠点倉庫コード項目がないが、SQLのWHERE文に拠点倉庫コードが存在するので確認お願い致します。**\r\n![](evi4.jpg)', '2023-06-09', '2023-06-13', 100, NULL, 0, 0, '2023-06-09 09:00:10', '2023-06-19 05:25:31', '{"id": 9387, "author": {"id": 31, "name": "朴 鍾昊"}, "status": {"id": 3, "name": "終了(completed)", "is_closed": true}, "project": {"id": 8, "name": "トランコムWMS"}, "subject": "【確認事項】【在庫受払照会】画面レイアウトの項目、SELECTのJOIN条件の質問、SELECTのWHERE条件の質問", "tracker": {"id": 1, "name": "課題"}, "category": {"id": 39, "name": "SPVW00201_在庫受払照会"}, "due_date": "2023-06-13", "priority": {"id": 1, "name": "通常"}, "closed_on": "2023-06-19T05:25:31Z", "created_on": "2023-06-09T09:00:10Z", "done_ratio": 100, "is_private": false, "start_date": "2023-06-09", "updated_on": "2023-06-19T05:25:31Z", "assigned_to": {"id": 9, "name": "江田 隆志"}, "description": "**１．画面レイアウトの「受注番号」、「購買伝票番号」、「在庫転送オーダー番号」ですが、「画面項目説明シート」に説明がないので確認させてください。**\\r\\n![](画面項目疑問点.jpg)\\r\\n\\r\\n**２．「処理概要シート」の125行目と132行目ですが、**\\r\\n125行目：「在庫受払履歴.仕入先コード⇒配送先コード」\\r\\n132行目：「在庫受払履歴.倉庫コード⇒配送先コード」ではないのでしょうか。\\r\\n\\r\\n![](evi1.jpg)\\r\\n![](evi2.jpg)\\r\\n![](evi3.jpg)\\r\\n\\r\\n**３．在庫受払テーブルには拠点倉庫コード項目がないが、SQLのWHERE文に拠点倉庫コードが存在するので確認お願い致します。**\\r\\n![](evi4.jpg)", "spent_hours": 0.0, "custom_fields": [{"id": 19, "name": "発生フェーズ", "value": "31"}, {"id": 18, "name": "顧客リリース日", "value": null}, {"id": 36, "name": "管理番号", "value": ""}, {"id": 50, "name": "水平展開", "value": null}], "fixed_version": {"id": 3, "name": "優先度：3"}, "estimated_hours": null, "total_spent_hours": 0.0, "total_estimated_hours": null}', '2026-05-05 09:21:16', '2026-05-05 09:22:01', '2026-05-05 09:22:01');
INSERT INTO `issues` (`id`, `connection_id`, `project_id`, `redmine_issue_id`, `tracker_id`, `tracker_name`, `status_id`, `status_name`, `priority_id`, `priority_name`, `author_id`, `author_name`, `assignee_id`, `assignee_name`, `subject`, `description`, `start_date`, `due_date`, `done_ratio`, `estimated_hours`, `spent_hours`, `is_closed`, `redmine_created_on`, `redmine_updated_on`, `raw_data_json`, `last_synced_at`, `created_at`, `updated_at`) VALUES
	(4119, 1, 41, 9385, 1, '課題', 3, '終了(completed)', 1, '通常', 208, 'NGUYEN DANG CHINH(BVN)', 9, '江田 隆志', '【確認事項】【SPOT01101‐ピッキング指示明細】・TOT060_PICKORDテーブルについて', '江田さん\r\n\r\nテーブル設計書のTOT060_PICKORDテーブルのTOT060_PICKORD.PCKDATETIMEはNOT NULL:\r\n![](QA_spot01101.PNG)\r\nSPOT01101‐ピッキング指示明細の基本設計書でのテーブル編集仕様 (取消ボタンを押下した時)シートにTOT060_PICKORD.PCKDATETIME = NULLと記載しています。\r\nなので、この項目を更新出来ないです。\r\n![](QA_spot01101_02.PNG)\r\nご確認よろしくお願いします。\r\n ', '2023-06-09', '2023-06-12', 100, NULL, 0, 0, '2023-06-09 08:33:20', '2023-07-06 12:38:04', '{"id": 9385, "author": {"id": 208, "name": "NGUYEN DANG CHINH(BVN)"}, "status": {"id": 3, "name": "終了(completed)", "is_closed": true}, "project": {"id": 8, "name": "トランコムWMS"}, "subject": "【確認事項】【SPOT01101‐ピッキング指示明細】・TOT060_PICKORDテーブルについて", "tracker": {"id": 1, "name": "課題"}, "category": {"id": 30, "name": "SPOT01101_ピッキング取消"}, "due_date": "2023-06-12", "priority": {"id": 1, "name": "通常"}, "closed_on": "2023-07-06T12:38:04Z", "created_on": "2023-06-09T08:33:20Z", "done_ratio": 100, "is_private": false, "start_date": "2023-06-09", "updated_on": "2023-07-06T12:38:04Z", "assigned_to": {"id": 9, "name": "江田 隆志"}, "description": "江田さん\\r\\n\\r\\nテーブル設計書のTOT060_PICKORDテーブルのTOT060_PICKORD.PCKDATETIMEはNOT NULL:\\r\\n![](QA_spot01101.PNG)\\r\\nSPOT01101‐ピッキング指示明細の基本設計書でのテーブル編集仕様 (取消ボタンを押下した時)シートにTOT060_PICKORD.PCKDATETIME = NULLと記載しています。\\r\\nなので、この項目を更新出来ないです。\\r\\n![](QA_spot01101_02.PNG)\\r\\nご確認よろしくお願いします。\\r\\n ", "spent_hours": 0.0, "custom_fields": [{"id": 19, "name": "発生フェーズ", "value": "31"}, {"id": 18, "name": "顧客リリース日", "value": null}, {"id": 36, "name": "管理番号", "value": ""}, {"id": 50, "name": "水平展開", "value": null}], "fixed_version": {"id": 3, "name": "優先度：3"}, "estimated_hours": null, "total_spent_hours": 0.0, "total_estimated_hours": null}', '2026-05-05 09:21:16', '2026-05-05 09:22:01', '2026-05-05 09:22:01'),
	(4120, 1, 41, 9384, 2, 'バグ', 3, '終了(completed)', 1, '通常', 104, 'Pham ThanhHau', 9, '江田 隆志', '【新WMS】【結合－バグ】【ロケ・品質・ロット変更】【SPST00501-0401　No3】変更数-変更可能数超過（単行）', '------\r\n\r\n### １．事象\r\n\r\n　.該当行の変更可能数より多く変更数を入力すると、「変更数の合計以上の変更可能数を登録することはできません。」が表示されること。\r\n![](image1.png)\r\n![](image2.png)\r\n\r\n------\r\n\r\n### ２．期待結果\r\n\r\n　該当行の変更可能数より多く変更数を入力すると、「変更可能数の合計が変更可能数の数より多いです。」が表示されること。\r\n\r\n\r\n\r\n------\r\n\r\n### ３．再現方法\r\n\r\n　１の補足として再現方法があれば手順を記載（要更新）\r\n\r\n\r\n------\r\n\r\n### ４．原因\r\n\r\n　commonmessageJPN.propertiesbの[ME000123:%1の合計以上の%2を登録することはできません。]で設定されているため\r\n\r\n------\r\n\r\n### ５．暫定対応\r\n\r\n　commonmessageJPN.propertiesbの[ME000123:%1の合計以上の%2を登録することはできません。]を\r\n　[ME000123:%1の合計が%2の数より多いです。]と変更して対応しました。\r\n ![](eramessage_123.jpg)\r\n\r\n\r\n------\r\n\r\n### ６．恒久対応\r\n\r\n　恒久対応内容を記載（要更新）\r\n\r\n------\r\n\r\n### ７．特記事項\r\n\r\n　その他特記事項があれば記載（要更新）\r\n\r\n------', '2023-06-09', '2023-06-11', 100, NULL, 0, 0, '2023-06-09 08:30:37', '2023-06-28 05:24:43', '{"id": 9384, "author": {"id": 104, "name": "Pham ThanhHau"}, "status": {"id": 3, "name": "終了(completed)", "is_closed": true}, "project": {"id": 8, "name": "トランコムWMS"}, "subject": "【新WMS】【結合－バグ】【ロケ・品質・ロット変更】【SPST00501-0401　No3】変更数-変更可能数超過（単行）", "tracker": {"id": 2, "name": "バグ"}, "category": {"id": 37, "name": "SPST00501_品質ロット変更"}, "due_date": "2023-06-11", "priority": {"id": 1, "name": "通常"}, "closed_on": "2023-06-28T05:24:43Z", "created_on": "2023-06-09T08:30:37Z", "done_ratio": 100, "is_private": false, "start_date": "2023-06-09", "updated_on": "2023-06-28T05:24:43Z", "assigned_to": {"id": 9, "name": "江田 隆志"}, "description": "------\\r\\n\\r\\n### １．事象\\r\\n\\r\\n　.該当行の変更可能数より多く変更数を入力すると、「変更数の合計以上の変更可能数を登録することはできません。」が表示されること。\\r\\n![](image1.png)\\r\\n![](image2.png)\\r\\n\\r\\n------\\r\\n\\r\\n### ２．期待結果\\r\\n\\r\\n　該当行の変更可能数より多く変更数を入力すると、「変更可能数の合計が変更可能数の数より多いです。」が表示されること。\\r\\n\\r\\n\\r\\n\\r\\n------\\r\\n\\r\\n### ３．再現方法\\r\\n\\r\\n　１の補足として再現方法があれば手順を記載（要更新）\\r\\n\\r\\n\\r\\n------\\r\\n\\r\\n### ４．原因\\r\\n\\r\\n　commonmessageJPN.propertiesbの[ME000123:%1の合計以上の%2を登録することはできません。]で設定されているため\\r\\n\\r\\n------\\r\\n\\r\\n### ５．暫定対応\\r\\n\\r\\n　commonmessageJPN.propertiesbの[ME000123:%1の合計以上の%2を登録することはできません。]を\\r\\n　[ME000123:%1の合計が%2の数より多いです。]と変更して対応しました。\\r\\n ![](eramessage_123.jpg)\\r\\n\\r\\n\\r\\n------\\r\\n\\r\\n### ６．恒久対応\\r\\n\\r\\n　恒久対応内容を記載（要更新）\\r\\n\\r\\n------\\r\\n\\r\\n### ７．特記事項\\r\\n\\r\\n　その他特記事項があれば記載（要更新）\\r\\n\\r\\n------", "spent_hours": 0.0, "custom_fields": [{"id": 19, "name": "発生フェーズ", "value": "25"}, {"id": 9, "name": "バグ混入フェーズ", "value": "4"}, {"id": 2, "name": "設計担当者", "value": ""}, {"id": 11, "name": "設計書修正要否", "value": ""}, {"id": 1, "name": "設計書修正対象", "value": ""}, {"id": 4, "name": "設計書修正内容", "value": ""}, {"id": 10, "name": "設計障害原因", "value": ""}, {"id": 15, "name": "設計書修正日", "value": ""}, {"id": 3, "name": "設計書レビュー担当者", "value": ""}, {"id": 22, "name": "設計書レビュー日", "value": ""}, {"id": 8, "name": "PG修正要否", "value": "2"}, {"id": 13, "name": "PG修正担当者", "value": ""}, {"id": 16, "name": "PG修正日", "value": ""}, {"id": 14, "name": "PG障害原因", "value": ""}, {"id": 12, "name": "PG修正対象", "value": ""}, {"id": 21, "name": "PGレビュー担当者", "value": ""}, {"id": 23, "name": "PGレビュー日", "value": ""}, {"id": 20, "name": "テスト環境リリース予定日", "value": ""}, {"id": 17, "name": "テスト環境リリース日", "value": ""}, {"id": 18, "name": "顧客リリース日", "value": ""}, {"id": 36, "name": "管理番号", "value": ""}, {"id": 50, "name": "水平展開", "value": null}], "fixed_version": {"id": 1, "name": "優先度：1"}, "estimated_hours": null, "total_spent_hours": 0.0, "total_estimated_hours": null}', '2026-05-05 09:21:16', '2026-05-05 09:22:01', '2026-05-05 09:22:01'),
	(4121, 1, 41, 9383, 2, 'バグ', 3, '終了(completed)', 1, '通常', 104, 'Pham ThanhHau', 9, '江田 隆志', '【新WMS】【結合－バグ】【ロケ・品質・ロット変更】ロケーションのマスタ存在チェック', '------\r\n\r\n### １．事象\r\n\r\n　ロケーションは何も入力せずに、確定ボタンを押下する時、マスタに存在しません。が表示されること。\r\n\r\n![](image.png)\r\n------\r\n\r\n### ２．期待結果\r\n\r\n　ロケーションは何も入力せずに、確定ボタンを押下する時、マスタに存在しません。が表示されないこと。\r\n\r\n\r\n\r\n------\r\n\r\n### ３．再現方法\r\n\r\n　１の補足として再現方法があれば手順を記載（要更新）\r\n\r\n\r\n------\r\n\r\n### ４．原因\r\n\r\n　事象が発生した原因を記載（要更新）\r\n\r\n------\r\n\r\n### ５．暫定対応\r\n\r\n　暫定対応があれば記載、なければ「なし」と記載（要更新）\r\n\r\n------\r\n\r\n### ６．恒久対応\r\n\r\n　恒久対応内容を記載（要更新）\r\n\r\n------\r\n\r\n### ７．特記事項\r\n\r\n　その他特記事項があれば記載（要更新）\r\n\r\n------', '2023-06-09', '2023-06-11', 100, NULL, 0, 0, '2023-06-09 08:20:35', '2023-06-23 02:59:49', '{"id": 9383, "author": {"id": 104, "name": "Pham ThanhHau"}, "status": {"id": 3, "name": "終了(completed)", "is_closed": true}, "project": {"id": 8, "name": "トランコムWMS"}, "subject": "【新WMS】【結合－バグ】【ロケ・品質・ロット変更】ロケーションのマスタ存在チェック", "tracker": {"id": 2, "name": "バグ"}, "category": {"id": 37, "name": "SPST00501_品質ロット変更"}, "due_date": "2023-06-11", "priority": {"id": 1, "name": "通常"}, "closed_on": "2023-06-23T02:59:49Z", "created_on": "2023-06-09T08:20:35Z", "done_ratio": 100, "is_private": false, "start_date": "2023-06-09", "updated_on": "2023-06-23T02:59:49Z", "assigned_to": {"id": 9, "name": "江田 隆志"}, "description": "------\\r\\n\\r\\n### １．事象\\r\\n\\r\\n　ロケーションは何も入力せずに、確定ボタンを押下する時、マスタに存在しません。が表示されること。\\r\\n\\r\\n![](image.png)\\r\\n------\\r\\n\\r\\n### ２．期待結果\\r\\n\\r\\n　ロケーションは何も入力せずに、確定ボタンを押下する時、マスタに存在しません。が表示されないこと。\\r\\n\\r\\n\\r\\n\\r\\n------\\r\\n\\r\\n### ３．再現方法\\r\\n\\r\\n　１の補足として再現方法があれば手順を記載（要更新）\\r\\n\\r\\n\\r\\n------\\r\\n\\r\\n### ４．原因\\r\\n\\r\\n　事象が発生した原因を記載（要更新）\\r\\n\\r\\n------\\r\\n\\r\\n### ５．暫定対応\\r\\n\\r\\n　暫定対応があれば記載、なければ「なし」と記載（要更新）\\r\\n\\r\\n------\\r\\n\\r\\n### ６．恒久対応\\r\\n\\r\\n　恒久対応内容を記載（要更新）\\r\\n\\r\\n------\\r\\n\\r\\n### ７．特記事項\\r\\n\\r\\n　その他特記事項があれば記載（要更新）\\r\\n\\r\\n------", "spent_hours": 0.0, "custom_fields": [{"id": 19, "name": "発生フェーズ", "value": "25"}, {"id": 9, "name": "バグ混入フェーズ", "value": "6"}, {"id": 2, "name": "設計担当者", "value": ""}, {"id": 11, "name": "設計書修正要否", "value": ""}, {"id": 1, "name": "設計書修正対象", "value": ""}, {"id": 4, "name": "設計書修正内容", "value": ""}, {"id": 10, "name": "設計障害原因", "value": ""}, {"id": 15, "name": "設計書修正日", "value": ""}, {"id": 3, "name": "設計書レビュー担当者", "value": ""}, {"id": 22, "name": "設計書レビュー日", "value": ""}, {"id": 8, "name": "PG修正要否", "value": "2"}, {"id": 13, "name": "PG修正担当者", "value": ""}, {"id": 16, "name": "PG修正日", "value": ""}, {"id": 14, "name": "PG障害原因", "value": ""}, {"id": 12, "name": "PG修正対象", "value": ""}, {"id": 21, "name": "PGレビュー担当者", "value": ""}, {"id": 23, "name": "PGレビュー日", "value": ""}, {"id": 20, "name": "テスト環境リリース予定日", "value": ""}, {"id": 17, "name": "テスト環境リリース日", "value": ""}, {"id": 18, "name": "顧客リリース日", "value": ""}, {"id": 36, "name": "管理番号", "value": ""}, {"id": 50, "name": "水平展開", "value": null}], "fixed_version": {"id": 1, "name": "優先度：1"}, "estimated_hours": null, "total_spent_hours": 0.0, "total_estimated_hours": null}', '2026-05-05 09:21:16', '2026-05-05 09:22:01', '2026-05-05 09:22:01'),
	(4122, 1, 41, 9378, 2, 'バグ', 3, '終了(completed)', 1, '通常', 135, '丹野 亜美(BP)', 9, '江田 隆志', '【新WMS】【結合－バグ】【出荷・出庫検品完了登録（欠品数入力子画面）】【動作確認】一度エラーメッセージを表示した後、表示ボタンを押下してもエラーメッセージがクリアされない', '------\r\n\r\n### １．事象\r\n\r\n　一度エラーメッセージを表示した後、表示ボタンを押下してもエラーメッセージがクリアされない\r\n\r\n\r\n------\r\n\r\n### ２．期待結果\r\n\r\n　エラーメッセージがクリアされること\r\n\r\n\r\n\r\n------\r\n\r\n### ３．再現方法\r\n\r\n　１の補足として再現方法があれば手順を記載（要更新）\r\n\r\n\r\n------\r\n\r\n### ４．原因\r\n\r\n　再検索する前に、既存のエラーメッセージを削除しなかったことの原因です。\r\n\r\n------\r\n\r\n### ５．暫定対応\r\n\r\n　再検索する前に、既存のエラーメッセージを削除しました。\r\n\r\n------\r\n\r\n### ６．恒久対応\r\n\r\n　再検索する前に、既存のエラーメッセージを削除すること。\r\n\r\n------\r\n\r\n### ７．特記事項\r\n\r\n　その他特記事項があれば記載（要更新）\r\n\r\n------\r\n', '2023-06-09', '2023-06-13', 100, NULL, 0, 0, '2023-06-09 06:49:43', '2023-06-16 06:13:15', '{"id": 9378, "author": {"id": 135, "name": "丹野 亜美(BP)"}, "status": {"id": 3, "name": "終了(completed)", "is_closed": true}, "project": {"id": 8, "name": "トランコムWMS"}, "subject": "【新WMS】【結合－バグ】【出荷・出庫検品完了登録（欠品数入力子画面）】【動作確認】一度エラーメッセージを表示した後、表示ボタンを押下してもエラーメッセージがクリアされない", "tracker": {"id": 2, "name": "バグ"}, "category": {"id": 26, "name": "SPOT00701_出荷・出庫検品完了登録"}, "due_date": "2023-06-13", "priority": {"id": 1, "name": "通常"}, "closed_on": "2023-06-16T06:13:15Z", "created_on": "2023-06-09T06:49:43Z", "done_ratio": 100, "is_private": false, "start_date": "2023-06-09", "updated_on": "2023-06-16T06:13:15Z", "assigned_to": {"id": 9, "name": "江田 隆志"}, "description": "------\\r\\n\\r\\n### １．事象\\r\\n\\r\\n　一度エラーメッセージを表示した後、表示ボタンを押下してもエラーメッセージがクリアされない\\r\\n\\r\\n\\r\\n------\\r\\n\\r\\n### ２．期待結果\\r\\n\\r\\n　エラーメッセージがクリアされること\\r\\n\\r\\n\\r\\n\\r\\n------\\r\\n\\r\\n### ３．再現方法\\r\\n\\r\\n　１の補足として再現方法があれば手順を記載（要更新）\\r\\n\\r\\n\\r\\n------\\r\\n\\r\\n### ４．原因\\r\\n\\r\\n　再検索する前に、既存のエラーメッセージを削除しなかったことの原因です。\\r\\n\\r\\n------\\r\\n\\r\\n### ５．暫定対応\\r\\n\\r\\n　再検索する前に、既存のエラーメッセージを削除しました。\\r\\n\\r\\n------\\r\\n\\r\\n### ６．恒久対応\\r\\n\\r\\n　再検索する前に、既存のエラーメッセージを削除すること。\\r\\n\\r\\n------\\r\\n\\r\\n### ７．特記事項\\r\\n\\r\\n　その他特記事項があれば記載（要更新）\\r\\n\\r\\n------\\r\\n", "spent_hours": 0.0, "custom_fields": [{"id": 19, "name": "発生フェーズ", "value": "25"}, {"id": 9, "name": "バグ混入フェーズ", "value": "6"}, {"id": 2, "name": "設計担当者", "value": ""}, {"id": 11, "name": "設計書修正要否", "value": ""}, {"id": 1, "name": "設計書修正対象", "value": ""}, {"id": 4, "name": "設計書修正内容", "value": ""}, {"id": 10, "name": "設計障害原因", "value": ""}, {"id": 15, "name": "設計書修正日", "value": ""}, {"id": 3, "name": "設計書レビュー担当者", "value": ""}, {"id": 22, "name": "設計書レビュー日", "value": ""}, {"id": 8, "name": "PG修正要否", "value": "2"}, {"id": 13, "name": "PG修正担当者", "value": ""}, {"id": 16, "name": "PG修正日", "value": ""}, {"id": 14, "name": "PG障害原因", "value": ""}, {"id": 12, "name": "PG修正対象", "value": ""}, {"id": 21, "name": "PGレビュー担当者", "value": ""}, {"id": 23, "name": "PGレビュー日", "value": ""}, {"id": 20, "name": "テスト環境リリース予定日", "value": ""}, {"id": 17, "name": "テスト環境リリース日", "value": ""}, {"id": 18, "name": "顧客リリース日", "value": ""}, {"id": 36, "name": "管理番号", "value": ""}, {"id": 50, "name": "水平展開", "value": null}], "fixed_version": {"id": 1, "name": "優先度：1"}, "estimated_hours": null, "total_spent_hours": 0.0, "total_estimated_hours": null}', '2026-05-05 09:21:16', '2026-05-05 09:22:01', '2026-05-05 09:22:01'),
	(4123, 1, 41, 9354, 2, 'バグ', 3, '終了(completed)', 4, '高い', 104, 'Pham ThanhHau', 9, '江田 隆志', '【新WMS】【結合－バグ】【ロケ・品質・ロット変更】明細行の非活性について', '------\r\n\r\n### １．事象\r\n\r\n　ロケーションが非活性になったとき、虫眼鏡アイコンを選択することができ、他のロケーションを選択することもできる状態。\r\n　品質が元の品質へ戻し後、ロケーション非活性がそのまま表示されること。\r\n![](image.png)\r\n\r\n\r\n------\r\n\r\n### ２．期待結果\r\n\r\n　ロケーションが非活性になったとき、虫眼鏡アイコンを選択することができないこと、または他のロケーションを選択することはできないこと。\r\n　品質が元の品質へ戻し後、ロケーションを入力できるようにすること。\r\n\r\n\r\n\r\n------\r\n\r\n### ３．再現方法\r\n\r\n　１の補足として再現方法があれば手順を記載（要更新）\r\n\r\n\r\n------\r\n\r\n### ４．原因\r\n\r\n　虫眼鏡ボタンをクリックしたときにロケーション項目の状態を確認してないため子画面が表示される。\r\n\r\n------\r\n\r\n### ５．暫定対応\r\n\r\n　ロケーション項目が編集可否である場合、子画面へ遷移しないように修正。\r\n\r\n------\r\n\r\n### ６．恒久対応\r\n\r\n　恒久対応内容を記載（要更新）\r\n\r\n------\r\n\r\n### ７．特記事項\r\n\r\n　その他特記事項があれば記載（要更新）\r\n\r\n------', '2023-06-09', '2023-06-11', 100, NULL, 0, 0, '2023-06-09 05:52:43', '2023-06-23 02:59:24', '{"id": 9354, "author": {"id": 104, "name": "Pham ThanhHau"}, "status": {"id": 3, "name": "終了(completed)", "is_closed": true}, "project": {"id": 8, "name": "トランコムWMS"}, "subject": "【新WMS】【結合－バグ】【ロケ・品質・ロット変更】明細行の非活性について", "tracker": {"id": 2, "name": "バグ"}, "category": {"id": 37, "name": "SPST00501_品質ロット変更"}, "due_date": "2023-06-11", "priority": {"id": 4, "name": "高い"}, "closed_on": "2023-06-23T02:59:24Z", "created_on": "2023-06-09T05:52:43Z", "done_ratio": 100, "is_private": false, "start_date": "2023-06-09", "updated_on": "2023-06-23T02:59:24Z", "assigned_to": {"id": 9, "name": "江田 隆志"}, "description": "------\\r\\n\\r\\n### １．事象\\r\\n\\r\\n　ロケーションが非活性になったとき、虫眼鏡アイコンを選択することができ、他のロケーションを選択することもできる状態。\\r\\n　品質が元の品質へ戻し後、ロケーション非活性がそのまま表示されること。\\r\\n![](image.png)\\r\\n\\r\\n\\r\\n------\\r\\n\\r\\n### ２．期待結果\\r\\n\\r\\n　ロケーションが非活性になったとき、虫眼鏡アイコンを選択することができないこと、または他のロケーションを選択することはできないこと。\\r\\n　品質が元の品質へ戻し後、ロケーションを入力できるようにすること。\\r\\n\\r\\n\\r\\n\\r\\n------\\r\\n\\r\\n### ３．再現方法\\r\\n\\r\\n　１の補足として再現方法があれば手順を記載（要更新）\\r\\n\\r\\n\\r\\n------\\r\\n\\r\\n### ４．原因\\r\\n\\r\\n　虫眼鏡ボタンをクリックしたときにロケーション項目の状態を確認してないため子画面が表示される。\\r\\n\\r\\n------\\r\\n\\r\\n### ５．暫定対応\\r\\n\\r\\n　ロケーション項目が編集可否である場合、子画面へ遷移しないように修正。\\r\\n\\r\\n------\\r\\n\\r\\n### ６．恒久対応\\r\\n\\r\\n　恒久対応内容を記載（要更新）\\r\\n\\r\\n------\\r\\n\\r\\n### ７．特記事項\\r\\n\\r\\n　その他特記事項があれば記載（要更新）\\r\\n\\r\\n------", "spent_hours": 0.0, "custom_fields": [{"id": 19, "name": "発生フェーズ", "value": "25"}, {"id": 9, "name": "バグ混入フェーズ", "value": "6"}, {"id": 2, "name": "設計担当者", "value": ""}, {"id": 11, "name": "設計書修正要否", "value": ""}, {"id": 1, "name": "設計書修正対象", "value": ""}, {"id": 4, "name": "設計書修正内容", "value": ""}, {"id": 10, "name": "設計障害原因", "value": ""}, {"id": 15, "name": "設計書修正日", "value": ""}, {"id": 3, "name": "設計書レビュー担当者", "value": ""}, {"id": 22, "name": "設計書レビュー日", "value": ""}, {"id": 8, "name": "PG修正要否", "value": "2"}, {"id": 13, "name": "PG修正担当者", "value": ""}, {"id": 16, "name": "PG修正日", "value": ""}, {"id": 14, "name": "PG障害原因", "value": ""}, {"id": 12, "name": "PG修正対象", "value": ""}, {"id": 21, "name": "PGレビュー担当者", "value": ""}, {"id": 23, "name": "PGレビュー日", "value": ""}, {"id": 20, "name": "テスト環境リリース予定日", "value": ""}, {"id": 17, "name": "テスト環境リリース日", "value": ""}, {"id": 18, "name": "顧客リリース日", "value": ""}, {"id": 36, "name": "管理番号", "value": ""}, {"id": 50, "name": "水平展開", "value": null}], "fixed_version": {"id": 1, "name": "優先度：1"}, "estimated_hours": null, "total_spent_hours": 0.0, "total_estimated_hours": null}', '2026-05-05 09:21:16', '2026-05-05 09:22:01', '2026-05-05 09:22:01'),
	(4124, 1, 41, 9353, 2, 'バグ', 3, '終了(completed)', 4, '高い', 104, 'Pham ThanhHau', 9, '江田 隆志', '【新WMS】【結合－バグ】【ロケ・品質・ロット変更】確定ボタンを押下する時に、システムエラー発生について', '------\r\n\r\n### １．事象\r\n\r\n　検索結果は１件の時に、ロケーションリンクをクリックし、ロケーションを変更して確定ボタンを押下するとシステムエラーが発生したこと。\r\n再現する方法は以下となります。\r\n![](image.png)\r\n\r\n------\r\n\r\n### ２．期待結果\r\n\r\n　設計書の通りに確定ボタンを押下する後、システムエラーが発せされなく、正常動けます。\r\n\r\n\r\n\r\n------\r\n\r\n### ３．再現方法\r\n\r\n　１の補足として再現方法があれば手順を記載（要更新）\r\n\r\n\r\n------\r\n\r\n### ４．原因\r\n\r\n　商品マスタで取得するデータがNullのためです。\r\n　（在庫移動実績(step1)TRの在庫移動数量単位（STOCKMVQTYUOM）がNot Nullで設定されています。）\r\n\r\n------\r\n\r\n### ５．暫定対応\r\n\r\n　商品コードが正常に動けるコードで変更して対応。\r\n\r\n------\r\n\r\n### ６．恒久対応\r\n\r\n　恒久対応内容を記載（要更新）\r\n\r\n------\r\n\r\n### ７．特記事項\r\n\r\n　その他特記事項があれば記載（要更新）\r\n\r\n------', '2023-06-09', '2023-06-11', 100, NULL, 0, 0, '2023-06-09 05:36:54', '2023-06-15 09:00:15', '{"id": 9353, "author": {"id": 104, "name": "Pham ThanhHau"}, "status": {"id": 3, "name": "終了(completed)", "is_closed": true}, "project": {"id": 8, "name": "トランコムWMS"}, "subject": "【新WMS】【結合－バグ】【ロケ・品質・ロット変更】確定ボタンを押下する時に、システムエラー発生について", "tracker": {"id": 2, "name": "バグ"}, "category": {"id": 37, "name": "SPST00501_品質ロット変更"}, "due_date": "2023-06-11", "priority": {"id": 4, "name": "高い"}, "closed_on": "2023-06-15T09:00:15Z", "created_on": "2023-06-09T05:36:54Z", "done_ratio": 100, "is_private": false, "start_date": "2023-06-09", "updated_on": "2023-06-15T09:00:15Z", "assigned_to": {"id": 9, "name": "江田 隆志"}, "description": "------\\r\\n\\r\\n### １．事象\\r\\n\\r\\n　検索結果は１件の時に、ロケーションリンクをクリックし、ロケーションを変更して確定ボタンを押下するとシステムエラーが発生したこと。\\r\\n再現する方法は以下となります。\\r\\n![](image.png)\\r\\n\\r\\n------\\r\\n\\r\\n### ２．期待結果\\r\\n\\r\\n　設計書の通りに確定ボタンを押下する後、システムエラーが発せされなく、正常動けます。\\r\\n\\r\\n\\r\\n\\r\\n------\\r\\n\\r\\n### ３．再現方法\\r\\n\\r\\n　１の補足として再現方法があれば手順を記載（要更新）\\r\\n\\r\\n\\r\\n------\\r\\n\\r\\n### ４．原因\\r\\n\\r\\n　商品マスタで取得するデータがNullのためです。\\r\\n　（在庫移動実績(step1)TRの在庫移動数量単位（STOCKMVQTYUOM）がNot Nullで設定されています。）\\r\\n\\r\\n------\\r\\n\\r\\n### ５．暫定対応\\r\\n\\r\\n　商品コードが正常に動けるコードで変更して対応。\\r\\n\\r\\n------\\r\\n\\r\\n### ６．恒久対応\\r\\n\\r\\n　恒久対応内容を記載（要更新）\\r\\n\\r\\n------\\r\\n\\r\\n### ７．特記事項\\r\\n\\r\\n　その他特記事項があれば記載（要更新）\\r\\n\\r\\n------", "spent_hours": 0.0, "custom_fields": [{"id": 19, "name": "発生フェーズ", "value": "25"}, {"id": 9, "name": "バグ混入フェーズ", "value": "8"}, {"id": 2, "name": "設計担当者", "value": ""}, {"id": 11, "name": "設計書修正要否", "value": ""}, {"id": 1, "name": "設計書修正対象", "value": ""}, {"id": 4, "name": "設計書修正内容", "value": ""}, {"id": 10, "name": "設計障害原因", "value": ""}, {"id": 15, "name": "設計書修正日", "value": ""}, {"id": 3, "name": "設計書レビュー担当者", "value": ""}, {"id": 22, "name": "設計書レビュー日", "value": ""}, {"id": 8, "name": "PG修正要否", "value": "2"}, {"id": 13, "name": "PG修正担当者", "value": ""}, {"id": 16, "name": "PG修正日", "value": ""}, {"id": 14, "name": "PG障害原因", "value": ""}, {"id": 12, "name": "PG修正対象", "value": ""}, {"id": 21, "name": "PGレビュー担当者", "value": ""}, {"id": 23, "name": "PGレビュー日", "value": ""}, {"id": 20, "name": "テスト環境リリース予定日", "value": ""}, {"id": 17, "name": "テスト環境リリース日", "value": ""}, {"id": 18, "name": "顧客リリース日", "value": ""}, {"id": 36, "name": "管理番号", "value": ""}, {"id": 50, "name": "水平展開", "value": null}], "fixed_version": {"id": 1, "name": "優先度：1"}, "estimated_hours": null, "total_spent_hours": 0.0, "total_estimated_hours": null}', '2026-05-05 09:21:16', '2026-05-05 09:22:01', '2026-05-05 09:22:01'),
	(4125, 1, 41, 9352, 2, 'バグ', 3, '終了(completed)', 7, '緊急', 202, '斎藤 雄太朗(BP)', 9, '江田 隆志', '【新WMS】【結合－バグ】【SPIN00401_入荷検品棚入】【SPIN00401-0202-NO.3】TRキーが旧版', '------\r\n\r\n### １．事象\r\n\r\n　TR系テーブルの登録時に使用しているprefixが旧版を使用している。\r\n　ZHJ、ZIJ、ZRJ、ZPJ\r\n\r\n------\r\n\r\n### ２．期待結果\r\n\r\n　新版を使用するようにする\r\n　\r\n生産入荷実績TR（TIN040_PDTRCVDRSLTTR）：TSN\r\n出荷返品実績TR（TIN040_ORDHNRSLTTR）：TSH\r\n幹線入庫実績TR（TIN040_TRLINRSLTTR）：TKN\r\n発注入荷実績TR（TIN050_ORDRCVDRSLTTR）：THN\r\n\r\n![](1.png)\r\n\r\n------\r\n\r\n### ３．再現方法\r\n\r\n　各受払区分（11,12,13,14,15）で入荷検品棚入を実施する\r\n\r\n------\r\n\r\n### ４．原因\r\n\r\n　自己間違いました。\r\n\r\n------\r\n\r\n### ５．暫定対応\r\n\r\n　新版通り修正しました。\r\n\r\n------\r\n\r\n### ６．恒久対応\r\n\r\n　セフルチェックをちゃんと実施すること。\r\n\r\n------\r\n\r\n### ７．特記事項\r\n\r\n　その他特記事項があれば記載（要更新）\r\n\r\n------', '2023-06-09', '2023-06-12', 100, NULL, 0, 0, '2023-06-09 04:56:45', '2023-06-16 05:38:07', '{"id": 9352, "author": {"id": 202, "name": "斎藤 雄太朗(BP)"}, "status": {"id": 3, "name": "終了(completed)", "is_closed": true}, "project": {"id": 8, "name": "トランコムWMS"}, "subject": "【新WMS】【結合－バグ】【SPIN00401_入荷検品棚入】【SPIN00401-0202-NO.3】TRキーが旧版", "tracker": {"id": 2, "name": "バグ"}, "category": {"id": 15, "name": "SPIN00401_入荷検品棚入"}, "due_date": "2023-06-12", "priority": {"id": 7, "name": "緊急"}, "closed_on": "2023-06-16T05:38:07Z", "created_on": "2023-06-09T04:56:45Z", "done_ratio": 100, "is_private": false, "start_date": "2023-06-09", "updated_on": "2023-06-16T05:38:07Z", "assigned_to": {"id": 9, "name": "江田 隆志"}, "description": "------\\r\\n\\r\\n### １．事象\\r\\n\\r\\n　TR系テーブルの登録時に使用しているprefixが旧版を使用している。\\r\\n　ZHJ、ZIJ、ZRJ、ZPJ\\r\\n\\r\\n------\\r\\n\\r\\n### ２．期待結果\\r\\n\\r\\n　新版を使用するようにする\\r\\n　\\r\\n生産入荷実績TR（TIN040_PDTRCVDRSLTTR）：TSN\\r\\n出荷返品実績TR（TIN040_ORDHNRSLTTR）：TSH\\r\\n幹線入庫実績TR（TIN040_TRLINRSLTTR）：TKN\\r\\n発注入荷実績TR（TIN050_ORDRCVDRSLTTR）：THN\\r\\n\\r\\n![](1.png)\\r\\n\\r\\n------\\r\\n\\r\\n### ３．再現方法\\r\\n\\r\\n　各受払区分（11,12,13,14,15）で入荷検品棚入を実施する\\r\\n\\r\\n------\\r\\n\\r\\n### ４．原因\\r\\n\\r\\n　自己間違いました。\\r\\n\\r\\n