	(4271, 1, 41, 8878, 1, '課題', 3, '終了(completed)', 4, '高い', 32, 'Paudel Pawan', 9, '江田 隆志', '【SPIN00501_入力完了登録】検索条件項目入荷予定日の初期表示について', '処理概要の表示状態を確認すると初期値が業務日付設定になっていますが画面項目説明の方確認すると\r\n初期表示が空欄と記載してあるのでどちらが正しいのか。\r\n★処理概要\r\n![](image1.png)\r\n★画面項目説明\r\n![](image2.png)\r\n', '2023-05-31', '2023-06-01', 100, NULL, 0, 0, '2023-05-31 12:31:25', '2023-06-05 05:46:37', '{"id": 8878, "author": {"id": 32, "name": "Paudel Pawan"}, "status": {"id": 3, "name": "終了(completed)", "is_closed": true}, "project": {"id": 8, "name": "トランコムWMS"}, "subject": "【SPIN00501_入力完了登録】検索条件項目入荷予定日の初期表示について", "tracker": {"id": 1, "name": "課題"}, "due_date": "2023-06-01", "priority": {"id": 4, "name": "高い"}, "closed_on": "2023-06-05T05:46:37Z", "created_on": "2023-05-31T12:31:25Z", "done_ratio": 100, "is_private": false, "start_date": "2023-05-31", "updated_on": "2023-06-05T05:46:37Z", "assigned_to": {"id": 9, "name": "江田 隆志"}, "description": "処理概要の表示状態を確認すると初期値が業務日付設定になっていますが画面項目説明の方確認すると\\r\\n初期表示が空欄と記載してあるのでどちらが正しいのか。\\r\\n★処理概要\\r\\n![](image1.png)\\r\\n★画面項目説明\\r\\n![](image2.png)\\r\\n", "spent_hours": 0.0, "custom_fields": [{"id": 19, "name": "発生フェーズ", "value": null}, {"id": 18, "name": "顧客リリース日", "value": null}, {"id": 36, "name": "管理番号", "value": null}, {"id": 50, "name": "水平展開", "value": null}], "estimated_hours": null, "total_spent_hours": 0.0, "total_estimated_hours": null}', '2026-05-05 09:21:16', '2026-05-05 09:22:03', '2026-05-05 09:22:03'),
